21:            FROM tenants t
22:            LEFT JOIN system_settings s ON s.tenant_id = t.tenant_id
23:           ORDER BY (s.setting_id IS NULL) ASC, t.tenant_id ASC
24:           LIMIT 1"
25:     );
26:     return $tenant;
27: }
