29: /** Storefront settings with safe defaults when no settings row exists. */
30: function storefront_settings($tenant) {
31:     $tenant_id = (int)($tenant['tenant_id'] ?? 0);
32:     $settings = $tenant_id > 0
33:         ? fetch_one("SELECT * FROM system_settings WHERE tenant_id = ? LIMIT 1", $tenant_id)
34:         : null;
35: 
36:     if (!$settings) {
37:         $settings = [
38:             'company_name'     => (string)($tenant['name'] ?? APP_NAME),
39:             'company_email'    => (string)($tenant['email'] ?? ''),
40:             'company_phone'    => (string)($tenant['phone'] ?? ''),
41:             'company_address'  => (string)($tenant['address'] ?? ''),
42:             'default_currency' => (string)($tenant['currency_code'] ?? 'TZS'),
43:             'logo_path'        => null,
44:             'apply_tax'        => 0,
45:         ];
46:     }
47:     return $settings;
48: }
49: 
50: /** Official business name shown throughout the storefront. */
51: function storefront_company_name($tenant, $settings = null) {
52:     if ($settings === null) $settings = storefront_settings($tenant);
53:     $name = trim((string)($settings['company_name'] ?? ''));
54:     if ($name === '') $name = trim((string)($tenant['name'] ?? ''));
55:     if ($name === '') $name = system_title((int)($tenant['tenant_id'] ?? 0));
56:     return $name;
57: }
58: 
59: /** Currency used by the public catalogue. */
60: function storefront_currency($tenant, $settings = null) {
61:     if (is_array($settings) && !empty($settings['default_currency'])) {
62:         return (string)$settings['default_currency'];
63:     }
64:     return (string)($tenant['currency_code'] ?? 'TZS');
65: }
66: 
67: /** Base path for this installation, with a trailing slash. */
68: function storefront_base_path() {
69:     static $base = null;
70:     if ($base !== null) return $base;
71: 
72:     $script = str_replace('\\', '/', (string)($_SERVER['SCRIPT_NAME'] ?? '/index.php'));
73:     $dir = rtrim(str_replace('\\', '/', dirname($script)), '/');
74:     if ($dir === '.' || $dir === '/') $dir = '';
75:     $base = $dir . '/';
76:     return $base;
77: }
78: 
79: /** Local URL for a storefront path. */
80: function storefront_url($path = '') {
