84: /** Absolute URL for feeds, structured data and canonical links. */
85: function storefront_absolute_url($path = '') {
86:     $scheme = (!empty($_SERVER['HTTPS']) && strtolower((string)$_SERVER['HTTPS']) !== 'off') ? 'https' : 'http';
87:     $host = (string)($_SERVER['HTTP_HOST'] ?? 'localhost');
