137: /** Public product path. The .htaccess rewrite also accepts the query-string fallback. */
138: function storefront_product_url($product) {
139:     $id = (int)($product['product_id'] ?? 0);
140:     $name = (string)($product['name'] ?? '');
141:     $slug = strtolower(trim((string)preg_replace('/[^a-z0-9]+/i', '-', $name), '-'));
142:     return 'product/' . $id . ($slug !== '' ? '/' . $slug : '');
