145: /** Correlated stock expression used by catalogue filters and cards. */
146: function storefront_stock_expr() {
147:     return "COALESCE((
148:         SELECT SUM(s.quantity)
149:           FROM inventory_stock s
150:           JOIN warehouses sw ON sw.warehouse_id = s.warehouse_id AND sw.tenant_id = s.tenant_id
151:          WHERE s.product_id = p.product_id
152:            AND s.tenant_id = p.tenant_id
153:            AND sw.is_godown = 0
154:     ), 0)";
155: }
156: 
157: /** Actual units sold, excluding cancelled orders, for popularity sorting. */
158: function storefront_sold_expr() {
159:     return "COALESCE((
160:         SELECT SUM(oi.quantity)
161:           FROM order_items oi
162:           JOIN orders o ON o.order_id = oi.order_id AND o.tenant_id = oi.tenant_id
163:          WHERE oi.product_id = p.product_id
164:            AND oi.tenant_id = p.tenant_id
165:            AND o.status <> 'cancelled'
166:     ), 0)";
167: }
