169: /** Common SELECT for public product rows. */
170: function storefront_product_select() {
171:     return "SELECT p.*, c.name AS category_name, u.name AS unit_name, u.short_name AS unit_short,
172:                    " . storefront_stock_expr() . " AS stock_qty,
173:                    " . storefront_sold_expr() . " AS sold_qty
174:               FROM products p
175:               LEFT JOIN product_categories c ON c.category_id = p.category_id AND c.tenant_id = p.tenant_id
176:               LEFT JOIN units_of_measurement u ON u.unit_id = p.unit_id AND u.tenant_id = p.tenant_id";
177: }
