179: /** Normalise catalogue filters supplied by a browser. */
180: function storefront_normalise_filters($filters = []) {
181:     $clean = [];
182:     $query = trim((string)($filters['q'] ?? ''));
183:     $clean['q'] = mb_substr($query, 0, 100);
184: 
185:     $clean['category'] = max(0, (int)($filters['category'] ?? 0));
186:     $clean['min_price'] = isset($filters['min_price']) && $filters['min_price'] !== ''
187:         ? max(0, (float)$filters['min_price']) : null;
188:     $clean['max_price'] = isset($filters['max_price']) && $filters['max_price'] !== ''
189:         ? max(0, (float)$filters['max_price']) : null;
190:     if ($clean['min_price'] !== null && $clean['max_price'] !== null && $clean['min_price'] > $clean['max_price']) {
191:         [$clean['min_price'], $clean['max_price']] = [$clean['max_price'], $clean['min_price']];
192:     }
193: 
194:     $clean['size'] = mb_substr(trim((string)($filters['size'] ?? '')), 0, 50);
195:     $clean['color'] = mb_substr(trim((string)($filters['color'] ?? '')), 0, 50);
196:     $availability = (string)($filters['availability'] ?? '');
197:     $clean['availability'] = in_array($availability, ['in', 'out'], true) ? $availability : '';
198:     $sort = (string)($filters['sort'] ?? '');
199:     $clean['sort'] = in_array($sort, ['newest', 'price_asc', 'price_desc', 'popular', 'name'], true) ? $sort : 'name';
200:     $clean['exclude_id'] = max(0, (int)($filters['exclude_id'] ?? 0));
201:     $clean['sold_only'] = !empty($filters['sold_only']);
