206: /** Build the shared WHERE clause for catalogue queries. */
207: function storefront_catalogue_where($tenant_id, array $filters, array &$params) {
208:     $filters = storefront_normalise_filters($filters);
209:     $stock_sql = storefront_stock_expr();
210:     $sold_sql = storefront_sold_expr();
211: 
212:     $sql = " WHERE p.tenant_id = ? AND p.is_active = 1";
213:     $params = [(int)$tenant_id];
214: 
215:     if ($filters['q'] !== '') {
216:         $like = '%' . $filters['q'] . '%';
217:         $sql .= " AND (p.name LIKE ? OR p.code LIKE ? OR p.sku LIKE ? OR p.barcode LIKE ? OR p.description LIKE ?)";
218:         array_push($params, $like, $like, $like, $like, $like);
219:     }
220:     if ($filters['category'] > 0) {
221:         $sql .= " AND p.category_id = ?";
222:         $params[] = (int)$filters['category'];
223:     }
224:     if ($filters['min_price'] !== null) {
225:         $sql .= " AND p.sale_price >= ?";
226:         $params[] = (float)$filters['min_price'];
227:     }
228:     if ($filters['max_price'] !== null) {
229:         $sql .= " AND p.sale_price <= ?";
230:         $params[] = (float)$filters['max_price'];
231:     }
232:     if ($filters['size'] !== '') {
233:         $sql .= " AND p.variant_size = ?";
234:         $params[] = $filters['size'];
235:     }
236:     if ($filters['color'] !== '') {
237:         $sql .= " AND p.variant_color = ?";
238:         $params[] = $filters['color'];
239:     }
240:     if ($filters['availability'] === 'in') {
241:         $sql .= " AND {$stock_sql} > 0";
242:     } elseif ($filters['availability'] === 'out') {
243:         $sql .= " AND {$stock_sql} <= 0";
244:     }
245:     if ($filters['exclude_id'] > 0) {
246:         $sql .= " AND p.product_id <> ?";
247:         $params[] = (int)$filters['exclude_id'];
248:     }
249:     if ($filters['sold_only']) {
