272:         'price_asc' => 'p.sale_price ASC, p.name ASC',
273:         'price_desc' => 'p.sale_price DESC, p.name ASC',
274:         'popular' => 'sold_qty DESC, p.name ASC',
275:         default => 'p.name ASC, p.product_id ASC',
276:     };
277: 
278:     $limit = max(1, min(100, (int)$limit));
279:     $offset = max(0, (int)$offset);
280:     $params[] = $limit;
281:     $params[] = $offset;
282: 
283:     return fetch_all(
284:         storefront_product_select() . $where . " ORDER BY {$order} LIMIT ? OFFSET ?",
285:         ...$params
286:     );
