362: /** Current cart rows with fresh catalogue prices. Returns [items, missing_product_ids]. */
363: function storefront_cart_details($tenant_id) {
364:     $items = [];
365:     $missing = [];
366:     foreach (storefront_cart() as $product_id => $quantity) {
367:         $product = storefront_product($tenant_id, $product_id);
368:         if (!$product) {
369:             $missing[] = (int)$product_id;
370:             continue;
371:         }
372:         $product['cart_quantity'] = (int)$quantity;
373:         $product['max_quantity'] = storefront_max_quantity($product);
