function code128_modules(string $text): array {
    $patterns = [...];
    $text = (string)$text;
    if ($text === '') return [];
    $values = [104]; // Start B
    $len = strlen($text);
    for ($i=0;$i<$len;$i++){
        $ord = ord($text[$i]);
        if ($ord < 32 || $ord > 126) return [];
        $values[] = $ord - 32;
    }
    $checksum = 104;
    for ($i=1;$i<count($values);$i++){ $checksum += $values[$i] * $i; }
    $values[] = $checksum % 103;
    $values[] = 106; // stop
    $bits=''; // build bars sequence
    foreach ($values as $v) {
        $pattern = $v === 106 ? '2331112' : $patterns[$v];
        // alternate bar/space starting with bar
        for ($k=0;$k<strlen($pattern);$k++){
            $width=(int)$pattern[$k];
            $bits .= str_repeat($k%2===0 ? '1':'0', $width);
        }
    }
    return $bits; // string of 1/0
}
```
Note for stop pattern 7 elements: starts bar and ends bar (7 elements => indices 0..6, even index bar). Good.

