JS:
```js
(function(){
  var openMenu = null, openBtn = null;
  function closeMenu(){ if(openMenu){ openMenu.classList.remove('is-open'); if(openBtn) openBtn.setAttribute('aria-expanded','false'); openMenu=null; openBtn=null; } }
  function position(menu, btn){
    var r = btn.getBoundingClientRect();
    var mw = menu.offsetWidth || 200;
    var mh = menu.offsetHeight || 200;
    var left = r.right - mw; // right align
    var top = r.bottom + 6;
    if (left < 8) left = 8;
    if (left + mw > window.innerWidth - 8) left = window.innerWidth - mw - 8;
    if (top + mh > window.innerHeight - 8) top = r.top - mh - 6;
    menu.style.left = left + 'px';
    menu.style.top = Math.max(8, top) + 'px';
  }
  document.addEventListener('click', function(e){
    var btn = e.target.closest('[data-product-actions]');
    if (btn) {
      e.preventDefault();
      var wrap = btn.closest('.product-actions');
      var menu = wrap.querySelector('.product-actions-menu');
      var isOpen = menu.classList.contains('is-open');
      closeMenu();
      if (!isOpen) { menu.classList.add('is-open'); btn.setAttribute('aria-expanded','true'); position(menu, btn); openMenu=menu; openBtn=btn; }
      return;
    }
    if (openMenu && openMenu.contains(e.target)) return; // allow link click; close after
    closeMenu();
  });
  document.addEventListener('keydown', function(e){ if(e.key==='Escape') closeMenu(); });
  window.addEventListener('resize', closeMenu);
  window.addEventListener('scroll', closeMenu, true);
})();
```
