.ws-product-thumb img { width: 100%; height: 100%; object-fit: cover; }
.ws-product-info { flex: 1 1 auto; min-width: 0; }
.ws-product-info strong { display: block; font-size: 13.5px; font-weight: 700; color: var(--ws-text); }
.ws-product-info small { display: block; color: var(--ws-muted); font-size: 11.5px; }
.ws-product-price { margin-top: 4px; font-size: 13px; font-weight: 700; color: var(--ws-primary-dark); }
.ws-product-qty { flex: 0 0 84px; display: flex; flex-direction: column; gap: 4px; }
.ws-product-qty label { color: var(--ws-muted); font-size: 10.5px; font-weight: 600; text-transform: uppercase; letter-spacing: .04em; }
.ws-product-qty input {
    width: 100%;
    min-height: 38px;
    padding: 6px 8px;
    border: 1px solid #d9dcea;
    border-radius: 8px;
    text-align: center;
    font-size: 13px;
}
.ws-product-qty input:focus { outline: none; border-color: var(--ws-primary); box-shadow: 0 0 0 3px var(--ws-primary-soft); }

.ws-order-summary { margin-top: 18px; }
.ws-summary-row { display: flex; justify-content: space-between; gap: 12px; padding: 7px 0; font-size: 13px; color: var(--ws-muted); }
.ws-summary-row strong { color: var(--ws-text); }
.ws-summary-total { border-top: 1px solid var(--ws-border); margin-top: 6px; padding-top: 12px; font-size: 15px; color: var(--ws-text); font-weight: 800; }

/* Detail lists */
.ws-detail-list { margin: 0; }
.ws-detail-list div { display: flex; justify-content: space-between; gap: 14px; padding: 9px 0; border-bottom: 1px solid #f0f1f7; font-size: 13px; }
.ws-detail-list div:last-child { border-bottom: 0; }
.ws-detail-list dt { color: var(--ws-muted); font-weight: 600; margin: 0; }
.ws-detail-list dd { margin: 0; text-align: right; font-weight: 600; overflow-wrap: anywhere; }

/* Status badges */
.ws-badge {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    padding: 3px 9px;
    border-radius: 999px;
    font-size: 11px;
    font-weight: 700;
    white-space: nowrap;
}
.ws-badge.is-active { background: #e7f6ee; color: #146c43; }
.ws-badge.is-suspended { background: #fdecea; color: #b42318; }
.ws-badge.is-neutral { background: #eef0f6; color: #4b5563; }

/* Activity timeline */
.ws-timeline { list-style: none; margin: 0; padding: 0; }
.ws-timeline li { position: relative; padding: 0 0 18px 28px; }
.ws-timeline li::before {
    content: '';
    position: absolute;
    left: 6px;
    top: 6px;
    width: 9px;
    height: 9px;
    border-radius: 50%;
    background: var(--ws-primary);
    box-shadow: 0 0 0 4px var(--ws-primary-soft);
}
.ws-timeline li::after {
    content: '';
    position: absolute;
    left: 10px;
    top: 18px;
    bottom: 0;
    width: 1px;
    background: var(--ws-border);
}
.ws-timeline li:last-child { padding-bottom: 0; }
.ws-timeline li:last-child::after { display: none; }
.ws-timeline strong { display: block; font-size: 13px; font-weight: 700; }
.ws-timeline span { display: block; color: var(--ws-muted); font-size: 12px; }

/* Footer */
.ws-footer { border-top: 1px solid var(--ws-border); background: #fff; padding: 18px 0; }
.ws-footer-inner { display: flex; justify-content: space-between; gap: 12px; flex-wrap: wrap; color: var(--ws-muted); font-size: 12px; }

@media (max-width: 1000px) {
    .ws-stat-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .ws-grid-2 { grid-template-columns: 1fr; }
    .ws-brand-text strong { max-width: 160px; }
    .ws-user-meta { display: none; }
}

@media (max-width: 760px) {
    .ws-header-inner { gap: 12px; min-height: 64px; }
    .ws-nav { order: 3; flex: 1 0 100%; flex-wrap: nowrap; overflow-x: auto; padding-bottom: 4px; }
    .ws-nav::-webkit-scrollbar { display: none; }
    .ws-nav-link { flex: 0 0 auto; }
    .ws-user { margin-left: auto; }
    .ws-logout span { display: none; }
    .ws-stat-grid { grid-template-columns: 1fr; }
    .ws-product-grid { grid-template-columns: 1fr; }
    .ws-product-row:nth-child(odd) { border-right: 0; }
    .ws-form-grid { grid-template-columns: 1fr; }
    .ws-page-head h1 { font-size: 21px; }
    .ws-container { padding: 0 15px; }
}

