if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf();
    if (!form_token_valid()) {
        flash_set('danger', 'This registration was already submitted. Please wait for our team to contact you.');
        redirect('wholesale-registration.php');
    }

    foreach (array_keys($sf_form) as $sf_field) {
        $sf_raw = $_POST[$sf_field] ?? '';
        $sf_form[$sf_field] = is_string($sf_raw) ? trim($sf_raw) : '';
    }

    if ($sf_form['business_name'] === '') {
        $sf_error = 'Please enter your business name.';
    } elseif (mb_strlen($sf_form['business_name']) > 191) {
        $sf_error = 'The business name is too long.';
    } elseif ($sf_form['contact_name'] === '') {
        $sf_error = 'Please enter the name of the person we should contact.';
    } elseif (mb_strlen($sf_form['contact_name']) > 191) {
        $sf_error = 'The contact name is too long.';
    } elseif ($sf_form['location'] === '') {
        $sf_error = 'Please enter your town, district or delivery area.';
    } elseif (mb_strlen($sf_form['location']) > 255) {
        $sf_error = 'The location is too long.';
    } else {
        $sf_phone_digits = preg_replace('/[^0-9]/', '', $sf_form['phone']);
        if ($sf_phone_digits === '' || strlen($sf_phone_digits) < 7) {
            $sf_error = 'Please enter a valid phone number.';
        } elseif (strlen($sf_phone_digits) > 15) {
            $sf_error = 'The phone number is too long.';
        } elseif ($sf_form['email'] !== '' && (!filter_var($sf_form['email'], FILTER_VALIDATE_EMAIL) || mb_strlen($sf_form['email']) > 191)) {
            $sf_error = 'Please enter a valid email address, or leave it empty.';
        } elseif ($sf_form['business_type'] !== '' && !in_array($sf_form['business_type'], $sf_business_types, true)) {
            $sf_error = 'Please choose a business type from the list.';
        } elseif ($sf_form['monthly_volume'] !== '' && !in_array($sf_form['monthly_volume'], $sf_volume_options, true)) {
            $sf_error = 'Please choose an estimated monthly volume from the list.';
        } elseif (mb_strlen($sf_form['product_interest']) > 255) {
            $sf_error = 'The product interest is too long.';
        } elseif (mb_strlen($sf_form['notes']) > 2000) {
            $sf_error = 'Please keep additional notes under 2,000 characters.';
        }
    }

    if ($sf_error === '') {
        $sf_notes = [];
        if ($sf_form['business_type'] !== '') $sf_notes[] = 'Business type: ' . $sf_form['business_type'];
        if ($sf_form['monthly_volume'] !== '') $sf_notes[] = 'Estimated monthly volume: ' . $sf_form['monthly_volume'];
        if ($sf_form['product_interest'] !== '') $sf_notes[] = 'Product interest: ' . $sf_form['product_interest'];
        if ($sf_form['notes'] !== '') $sf_notes[] = "Notes:\n" . $sf_form['notes'];
        $sf_notes[] = 'Submitted through the public wholesale registration page.';

        try {
            $conn->begin_transaction();
            $sf_lead_number = next_document_number($sf_tenant_id, 'lead', 'LEAD');
            $sf_stmt = $conn->prepare(
                "INSERT INTO leads
                    (tenant_id, lead_number, contact_name, company_name, phone, email, location, source, status, notes)
                 VALUES (?, ?, ?, ?, ?, ?, ?, 'wholesale', 'new', ?)"
            );
            if (!$sf_stmt) throw new RuntimeException($conn->error);
            $sf_notes_text = implode("\n", $sf_notes);
            $sf_stmt->bind_param(
                'isssssss',
                $sf_tenant_id,
                $sf_lead_number,
                $sf_form['contact_name'],
                $sf_form['business_name'],
                $sf_form['phone'],
                $sf_form['email'],
                $sf_form['location'],
                $sf_notes_text
            );
            if (!$sf_stmt->execute()) throw new RuntimeException($sf_stmt->error);
            $sf_lead_id = (int)$sf_stmt->insert_id;
            $sf_stmt->close();

            record_lead_activity(
                $sf_lead_id,
                $sf_tenant_id,
                'created',
                'Wholesale registration received',
                'A business asked to be registered as a wholesale customer. Review the details and follow up.'
            );

            $conn->commit();
            consume_form_token();
            redirect('wholesale-registration.php?sent=1&ref=' . urlencode($sf_lead_number));
        } catch (Throwable $sf_exception) {
            $conn->rollback();
            $sf_error = 'We could not save your registration right now. Please try again or contact us directly.';
        }
    }
}

