.product-actions-divider { height: 1px; margin: 5px 4px; background: #edf0f5; }

/* Wholesale activity timeline (admin screens) */
.ws-timeline { list-style: none; margin: 0; padding: 0; }
.ws-timeline li { position: relative; padding: 0 0 16px 26px; }
.ws-timeline li::before {
  content: '';
  position: absolute;
  left: 5px;
  top: 6px;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--primary);
  box-shadow: 0 0 0 4px var(--primary-soft);
}
.ws-timeline li::after {
  content: '';
  position: absolute;
  left: 9px;
  top: 18px;
  bottom: 0;
  width: 1px;
  background: var(--border, #e6e8f0);
}
.ws-timeline li:last-child { padding-bottom: 0; }
.ws-timeline li:last-child::after { display: none; }
.ws-timeline strong { display: block; font-size: 13px; font-weight: 700; }
.ws-timeline span { display: block; color: #6b7280; font-size: 12px; }

