/* ---------------- Search & filter bar ---------------- */
.sf-filterbar {
    background: #fff;
    border-bottom: 1px solid var(--sf-border);
}
.sf-filterbar-form {
    display: flex;
    align-items: flex-end;
    gap: 12px;
    flex-wrap: wrap;
    padding: 14px 0;
}
.sf-filterbar-search {
    display: flex;
    flex: 1 1 300px;
    min-width: 220px;
}
.sf-filterbar-search input {
    flex: 1 1 auto;
    min-width: 0;
    height: 42px;
    padding: 0 14px;
    border: 1px solid var(--sf-border-dark);
    border-right: 0;
    border-radius: 8px 0 0 8px;
    background: #fff;
    color: var(--sf-text);
    font-family: inherit;
    font-size: 13px;
}
.sf-filterbar-search input:focus { outline: none; border-color: var(--sf-accent); box-shadow: 0 0 0 3px var(--sf-accent-soft); }
.sf-filterbar-search button {
    flex: 0 0 52px;
    height: 42px;
    border: 1px solid var(--sf-accent);
    border-radius: 0 8px 8px 0;
    background: var(--sf-accent);
    color: #fff;
    cursor: pointer;
}
.sf-filterbar-search button:hover { background: var(--sf-accent-hover); }
.sf-filterbar-field { display: flex; flex-direction: column; gap: 4px; min-width: 130px; }
.sf-filterbar-field label {
    color: var(--sf-dark);
    font-size: 10.5px;
    font-weight: 800;
    letter-spacing: .08em;
    text-transform: uppercase;
}
.sf-filterbar-field select {
    height: 42px;
    padding: 0 10px;
    border: 1px solid var(--sf-border-dark);
    border-radius: 8px;
    background: #fff;
    color: var(--sf-text);
    font-family: inherit;
    font-size: 13px;
}
.sf-filterbar-field select:focus { outline: none; border-color: var(--sf-accent); box-shadow: 0 0 0 3px var(--sf-accent-soft); }
.sf-filterbar-apply {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 7px;
    height: 42px;
    padding: 0 18px;
    border: 1px solid var(--sf-dark);
    border-radius: 8px;
    background: var(--sf-dark);
    color: #fff;
    font-size: 13px;
    font-weight: 700;
    cursor: pointer;
}
.sf-filterbar-apply:hover { background: var(--sf-accent); border-color: var(--sf-accent); }
.sf-filterbar-reset {
    display: inline-flex;
    align-items: center;
    height: 42px;
    color: var(--sf-accent);
    font-size: 13px;
    font-weight: 700;
}
.sf-filterbar-reset:hover { text-decoration: underline; }

/* ---------------- Info pages (About / Help) ---------------- */
.sf-info-hero { padding: 6px 0 26px; border-bottom: 1px solid var(--sf-border); }
.sf-info-eyebrow {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    padding: 5px 12px;
    border-radius: 999px;
    background: var(--sf-accent-soft);
    color: var(--sf-accent-hover);
    font-size: 11px;
    font-weight: 800;
    letter-spacing: .1em;
    text-transform: uppercase;
}
.sf-info-hero h1 {
    margin: 12px 0 10px;
    color: var(--sf-dark);
    font-size: clamp(30px, 3.4vw, 44px);
    font-weight: 800;
    letter-spacing: -.035em;
    line-height: 1.1;
}
.sf-info-hero p { max-width: 70ch; margin: 0; color: var(--sf-muted); font-size: 15px; line-height: 1.75; }
.sf-info-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 18px; margin: 28px 0 34px; }
.sf-info-card {
    padding: 22px;
    border: 1px solid var(--sf-border);
    border-radius: 14px;
    background: #fff;
}
.sf-info-card > i {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 40px;
    height: 40px;
    margin-bottom: 12px;
    border-radius: 11px;
    background: var(--sf-accent-soft);
    color: var(--sf-accent);
    font-size: 17px;
}
.sf-info-card h2 { margin: 0 0 8px; color: var(--sf-dark); font-size: 17px; font-weight: 800; }
.sf-info-card p { margin: 0; color: var(--sf-muted); font-size: 13.5px; line-height: 1.7; }
.sf-info-section { padding: 28px 0 8px; border-top: 1px solid var(--sf-border); }
.sf-info-section h2 { margin: 0 0 14px; color: var(--sf-dark); font-size: 22px; font-weight: 800; }
.sf-info-contact p { display: flex; align-items: center; gap: 9px; margin: 0 0 8px; color: var(--sf-muted); font-size: 14px; }
.sf-info-contact i { color: var(--sf-accent); width: 16px; text-align: center; }
.sf-info-actions { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 18px; }
.sf-help-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; margin: 28px 0 34px; }
.sf-help-card {
    padding: 20px 22px;
    border: 1px solid var(--sf-border);
    border-radius: 14px;
    background: #fff;
}
.sf-help-card h2 { display: flex; align-items: center; gap: 9px; margin: 0 0 8px; color: var(--sf-dark); font-size: 16px; font-weight: 800; }
.sf-help-card h2 i { color: var(--sf-accent); }
.sf-help-card p { margin: 0; color: var(--sf-muted); font-size: 13.5px; line-height: 1.7; }

/* ---------------- Responsive ---------------- */

