            $html .= '<a class="' . $class . '" role="menuitem" href="' . e($item['href']) . '"' . $attrs . '>' . $icon . e($item['label']) . '</a>';
        } elseif (!empty($item['form'])) {
            $form = $item['form'];
            $html .= '<form method="' . e($form['method'] ?? 'POST') . '" action="' . e($form['action']) . '" class="row-actions-form"' . (!empty($form['confirm']) ? ' onsubmit="return confirm(\'' . e($form['confirm']) . '\');"' : '') . '>';
            if (($form['method'] ?? 'POST') !== 'GET') $html .= csrf_field();
            foreach (($form['fields'] ?? []) as $k => $v) { $html .= '<input type="hidden" name="' . e($k) . '" value="' . e($v) . '">'; }
            $html .= '<button type="submit" class="' . $class . '" role="menuitem">' . $icon . e($item['label']) . '</button></form>';
        } else {
            $attrs = '';
            foreach (($item['attrs'] ?? []) as $k => $v) { $attrs .= ' ' . $k . '="' . e($v) . '"'; }
            $html .= '<button type="button" class="' . $class . '" role="menuitem"' . $attrs . '>' . $icon . e($item['label']) . '</button>';
        }
    }
    return $html . '</div></div>';
}
}
