JS:
```js
(function(){
  var feed = document.getElementById('notifyFeed');
  if (!feed) return;
  var items = Array.prototype.slice.call(feed.querySelectorAll('.notify-item'));
  var groups = Array.prototype.slice.call(feed.querySelectorAll('.notify-group'));
  var chips = Array.prototype.slice.call(document.querySelectorAll('.notify-chip'));
  var search = document.getElementById('notifySearch');
  var empty = document.getElementById('notifyNoResults');
  var visibleCount = document.getElementById('notifyVisibleCount');
  var activeFilter = 'all';

  function apply(){
    var q = (search.value || '').trim().toLowerCase();
    var shown = 0;
    items.forEach(function(item){
      var matchesFilter = activeFilter === 'all' || (activeFilter === 'unread' ? item.dataset.unread === '1' : item.dataset.category === activeFilter);
      var matchesSearch = q === '' || (item.dataset.search || '').indexOf(q) !== -1;
      var show = matchesFilter && matchesSearch;
      item.hidden = !show; // use hidden attribute
      if (show) shown++;
    });
    groups.forEach(function(group){
      var any = group.querySelectorAll('.notify-item:not([hidden])').length > 0;
      group.hidden = !any;
    });
    if (empty) empty.hidden = shown !== 0;
    if (visibleCount) visibleCount.textContent = shown + ' of ' + items.length;
  }
  chips.forEach(function(chip){
    chip.addEventListener('click', function(){
      chips.forEach(function(c){ c.classList.remove('is-active'); c.setAttribute('aria-pressed','false'); });
      chip.classList.add('is-active'); chip.setAttribute('aria-pressed','true');
      activeFilter = chip.dataset.filter;
      apply();
    });
  });
  if (search) search.addEventListener('input', apply);
  apply();
})();
```

