.notify-tone-warning { background: var(--warning-soft); color: #b97a09; }

.notify-toolbar {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 16px;
}
.notify-chips { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.notify-chip {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 7px 14px;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: #fff;
  color: var(--text-muted);
  font-size: 12.5px;
  font-weight: 700;
  cursor: pointer;
  transition: background .15s ease, border-color .15s ease, color .15s ease, box-shadow .15s ease;
}
.notify-chip span {
  padding: 1px 7px;
  border-radius: 999px;
  background: #f1f3f9;
  color: #5b6477;
  font-size: 10.5px;
  font-weight: 800;
}
.notify-chip:hover { border-color: #f0c9cd; color: var(--primary); }
.notify-chip.is-active {
  background: var(--primary);
  border-color: var(--primary);
  color: #fff;
  box-shadow: 0 6px 16px rgba(190, 36, 48, .22);
}
.notify-chip.is-active span { background: rgba(255, 255, 255, .22); color: #fff; }

.notify-search { position: relative; margin-left: auto; min-width: 230px; }
.notify-search i {
  position: absolute;
  left: 13px;
  top: 50%;
  transform: translateY(-50%);
  color: #9a94a8;
  font-size: 13px;
  pointer-events: none;
}
.notify-search input {
  width: 100%;
  padding: 9px 14px 9px 36px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: #fff;
  color: var(--text);
  font-size: 13px;
  outline: none;
  transition: border-color .15s ease, box-shadow .15s ease;
}
.notify-search input:focus { border-color: #f0c9cd; box-shadow: 0 0 0 3px var(--primary-soft); }
.notify-search input::placeholder { color: #a49eb2; }

.notify-panel {
  overflow: hidden;
  margin-bottom: 22px;
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
}
.notify-panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 16px 22px;
  border-bottom: 1px solid var(--border-soft);
}
.notify-panel-head h2 { margin: 0; font-size: 14.5px; font-weight: 700; }
.notify-panel-count { font-size: 11.5px; font-weight: 600; color: var(--text-muted); }

.notify-feed { padding: 8px 10px 14px; }
.notify-group[hidden] { display: none; }
.notify-group + .notify-group { margin-top: 4px; }
.notify-group-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 12px 6px;
  font-size: 10.5px;
  font-weight: 800;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: #9a94a8;
}
.notify-group-head span:last-child {
  padding: 0 8px;
  border-radius: 999px;
  background: #f1f3f9;
  color: #6b6478;
  font-size: 10px;
  letter-spacing: 0;
}

.notify-item {
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: 14px;
  padding: 14px 12px;
  border-radius: 12px;
  color: var(--text);
  text-decoration: none;
  transition: background .15s ease;
}
.notify-item[hidden] { display: none; }
.notify-item:hover { background: #faf9fc; color: var(--text); text-decoration: none; }
.notify-item.is-unread { background: linear-gradient(90deg, var(--primary-soft), rgba(251, 234, 236, .35)); }
.notify-item.is-unread:hover { background: linear-gradient(90deg, #f8dfe2, rgba(251, 234, 236, .55)); }
.notify-item-icon {
  width: 42px;
  height: 42px;
  border-radius: 12px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-size: 16px;
  border: 1px solid rgba(23, 17, 65, .05);
}
.notify-item-body { min-width: 0; flex: 1 1 auto; }
.notify-item-top { display: flex; align-items: center; gap: 8px; }
.notify-item-title { font-size: 13.5px; font-weight: 800; line-height: 1.35; }
.notify-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
  background: var(--primary);
  box-shadow: 0 0 0 3px var(--primary-soft);
}
.notify-item-message {
  display: block;
  margin-top: 3px;
  font-size: 12.5px;
  line-height: 1.5;
  color: var(--text-muted);
}
.notify-item-meta {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  margin-top: 7px;
  font-size: 11px;
  color: #9a94a8;
}
.notify-item-tag {
  display: inline-flex;
  align-items: center;
  padding: 2px 8px;
  border-radius: 999px;
  font-size: 9.5px;
  font-weight: 800;
  letter-spacing: .04em;
  text-transform: uppercase;
}
.notify-item-date { opacity: .8; }
.notify-item-arrow {
  padding-top: 9px;
  color: #c4bfcd;
  font-size: 20px;
  line-height: 1;
  transition: color .15s ease, transform .15s ease;
}
.notify-item:hover .notify-item-arrow { color: var(--primary); transform: translateX(2px); }

.notify-no-results {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
  padding: 46px 20px;
  text-align: center;
  color: var(--text-muted);
}
.notify-no-results[hidden] { display: none; }
.notify-no-results i { margin-bottom: 4px; font-size: 30px; color: #c4bfcd; }
.notify-no-results strong { font-size: 14px; color: var(--text); }
.notify-no-results p { margin: 0; font-size: 12.5px; }

.notify-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 56px 20px;
  text-align: center;
  color: var(--text-muted);
}
.notify-empty i { margin-bottom: 4px; font-size: 40px; color: #c4bfcd; }
.notify-empty strong { font-size: 15px; color: var(--text); }
.notify-empty p { margin: 0; max-width: 400px; font-size: 12.5px; }

@media (max-width: 991.98px) {
  .notify-stats { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 575.98px) {
  .notify-hero { align-items: flex-start; padding: 20px; }
  .notify-hero-title { font-size: 20px; }
  .notify-hero-actions { width: 100%; }
  .notify-hero-actions .btn { width: 100%; }
  .notify-stats { gap: 10px; }
  .notify-stat { padding: 12px; }
  .notify-stat-value { font-size: 19px; }
  .notify-toolbar { align-items: stretch; }
  .notify-chips { width: 100%; }
  .notify-search { width: 100%; min-width: 0; margin-left: 0; }
  .notify-feed { padding: 6px 6px 12px; }
  .notify-item { gap: 11px; padding: 12px 8px; }
  .notify-item-date { display: none; }
  .notify-item-arrow { display: none; }
}

