    $stmt = $conn->prepare(
        "INSERT INTO sidebar_badge_seen (tenant_id, user_id, section, seen_at)
         VALUES (?, ?, ?, NOW())
         ON DUPLICATE KEY UPDATE seen_at = NOW()"
    );
    if (!$stmt) {
        return;
    }
