        $params = [$tenant_id, ...$visibility_params];
        if (!empty($seen['orders'])) {
            $sql .= ' AND (o.created_at > ? OR o.updated_at > ?)';
            $params[] = $seen['orders'];
            $params[] = $seen['orders'];
        }
        $row = fetch_one($sql, ...$params);
        $counts['orders'] = (int)($row['c'] ?? 0);
