                $scope_parts[] = 't.destination_warehouse_id IN (' . $id_list . ')';
            }
            if (!empty($shop_ids)) {
                $scope_parts[] = 't.destination_shop_id IN (' . implode(',', array_map('intval', $shop_ids)) . ')';
            }
            if (!$scope_parts) {
                $sql = '';
            } else {
                $sql .= ' AND (' . implode(' OR ', $scope_parts) . ')';
            }
