@'
<?php
declare(strict_types=1);

if (PHP_SAPI !== 'cli') {
    http_response_code(403);
    exit("CLI only.\n");
}

require_once __DIR__ . '/../config.php';
while (ob_get_level() > 0) ob_end_clean();

if (!in_array(DB_HOST, ['127.0.0.1', 'localhost', '::1'], true)) {
    fwrite(STDERR, "Refusing to clean a non-local database.\n");
    exit(1);
}

$tenant_id = 1;

$tables = [
    'sales_return_items', 'sales_returns',
    'pos_payments', 'pos_order_items', 'pos_orders', 'pos_sessions',
    'payments', 'invoice_items', 'invoices',
    'quotation_items', 'quotations',
    'order_stock_reservations', 'order_items', 'orders',
    'storefront_lead_request_items', 'storefront_lead_requests',
    'lead_notification_reads', 'storefront_request_notification_reads', 'leads',
    'stock_transfer_items', 'stock_transfers', 'godown_receipts',
    'inventory_movements', 'inventory_stock',
    'purchases', 'expense_items', 'expenses', 'journal_entries', 'deals',
    'notifications', 'wholesale_notifications', 'sidebar_badge_seen',
    'activities', 'audit_logs',
    'contacts', 'wholesaler_accounts', 'suppliers', 'storefront_subscribers',
];

echo "Cleaning business data...\n";
echo "Database: " . DB_NAME . "\n";

$conn->query("SET FOREIGN_KEY_CHECKS=0");
try {
    $conn->begin_transaction();
    foreach ($tables as $table) {
        if (!db_table_exists($table)) {
            echo "  = skip missing {$table}\n";
            continue;
        }
        if (!$conn->query("DELETE FROM `{$table}`")) {
            throw new RuntimeException("Could not clear {$table}: " . $conn->error);
        }
        echo "  - cleared {$table}\n";
    }
    $conn->commit();

    // Reset auto-increment counters for cleared tables.
    $auto_tables = [];
    foreach (fetch_all(
        "SELECT TABLE_NAME
           FROM information_schema.COLUMNS
          WHERE TABLE_SCHEMA = DATABASE() AND EXTRA LIKE '%auto_increment%'"
    ) as $row) {
        $auto_tables[(string)$row['TABLE_NAME']] = true;
    }
    foreach ($tables as $table) {
        if (isset($auto_tables[$table])) {
            $conn->query("ALTER TABLE `{$table}` AUTO_INCREMENT = 1");
        }
    }

    // Fresh document numbers.
    $conn->query("DELETE FROM document_sequences");
    $conn->query("UPDATE system_settings SET invoice_next_number = 1001 WHERE tenant_id = " . (int)$tenant_id);

    // Rebuild starting stock: 50 in each godown, 5 in each shop/store.
    $products = fetch_all(
        "SELECT product_id, tenant_id, COALESCE(min_stock_level, 5) AS min_stock_level
           FROM products
          WHERE is_service = 0"
    );
    $warehouses = fetch_all(
        "SELECT warehouse_id, tenant_id, is_godown
           FROM warehouses
          WHERE is_active = 1"
    );

    $stmt = $conn->prepare(
        "INSERT INTO inventory_stock
            (tenant_id, product_id, warehouse_id, quantity, reorder_level, updated_at, last_counted_at)
         VALUES (?, ?, ?, ?, ?, NOW(), NOW())"
    );
    if (!$stmt) throw new RuntimeException($conn->error);

    $stock_rows = 0;
    foreach ($products as $product) {
        foreach ($warehouses as $warehouse) {
            if ((int)$product['tenant_id'] !== (int)$warehouse['tenant_id']) continue;
            $quantity = (int)$warehouse['is_godown'] === 1 ? 50.0 : 5.0;
            $reorder = (float)$product['min_stock_level'];
            $pid = (int)$product['product_id'];
            $wid = (int)$warehouse['warehouse_id'];
            $tid = (int)$product['tenant_id'];
            $stmt->bind_param('iiidd', $tid, $pid, $wid, $quantity, $reorder);
            if (!$stmt->execute()) {
                throw new RuntimeException('Could not seed inventory stock: ' . $stmt->error);
            }
            $stock_rows++;
        }
    }
    $stmt->close();

    echo "  + rebuilt {$stock_rows} inventory stock row(s)\n";
    echo "  + document sequences reset\n";
    echo "  + invoice next number reset to 1001\n";
    echo "Cleanup complete.\n";
} catch (Throwable $ex) {
    $conn->rollback();
    fwrite(STDERR, "Cleanup failed: " . $ex->getMessage() . "\n");
    exit(1);
} finally {
    $conn->query("SET FOREIGN_KEY_CHECKS=1");
}
