/** Format a stock quantity without noisy trailing zeroes. */
function format_quantity($value) {
    $formatted = number_format((float)$value, 2, '.', '');
    $formatted = rtrim(rtrim($formatted, '0'), '.');
    return $formatted === '' || $formatted === '-0' ? '0' : $formatted;
}

