630:     function recalcTotals() {
631:         var subtotal = 0, tax = 0;
632:         $('#cartItems .cart-row').each(function () {
633:             var price = parseFloat($(this).find('.cart-price').val()) || 0;
634:             var qty = parseFloat($(this).find('.cart-qty').val()) || 0;
635:             var line = price * qty;
636:             var rate = parseFloat($(this).data('tax')) || 0;
637:             var lineTax = taxEnabled ? line * rate / 100 : 0;
638:             subtotal += line;
639:             tax += lineTax;
640:             $(this).find('.cart-line-total').text(fmtMoney(line + lineTax));
641:         });
642:         $('#ttSubtotal').text(fmtMoney(subtotal));
643:         $('#ttTax').text(fmtMoney(tax));
644:         $('#ttTaxRow').css('display', taxEnabled ? '' : 'none');
645:         var d = currentDiscount;
646:         if (d > subtotal + tax) d = subtotal + tax;
647:         $('#ttDiscount').text(fmtMoney(d));
648:         $('#ttDiscountRow').css('display', d > 0 ? '' : 'none');
649:         var grand = subtotal + tax - d;
650:         if (grand < 0) grand = 0;
651:         $('#ttGrand').text(fmtMoney(grand));
652:         $('#checkoutTotal').text(fmtMoney(grand));
653:         syncAmountPaid(grand);
654:     }
