662:         var paid = parseFloat($('#amountPaidInput').val());
663:         if (isNaN(paid) || paid < 0) paid = 0;
664:         var balance = lastGrand - paid;
665:         if (balance < 0) balance = 0;
666:         $('#balanceDisplay').val(fmtMoney(balance));
667:     }
