745:         });
746:         $('#posSearch').on('keydown', function (e) {
747:             if (e.key === 'Enter') {
748:                 e.preventDefault();
749:                 var q = $(this).val().trim().toLowerCase();
750:                 var row = null;
751:                 if (q !== '') {
