761:                     addToCart(row.data('id'));
762:                     $(this).val('');
763:                 }
764:             }
765:         });
766: 
767:         $('#discountInput').on('input', function () {
768:             var d = parseFloat($(this).val()) || 0;
769:             if (d < 0) d = 0;
770:             currentDiscount = d;
771:             recalcTotals();
772:         });
773: 
774:         $('#applyTax').on('change', function () {
775:             taxEnabled = this.checked ? 1 : 0;
776:             $('#ttTaxRow').toggle(!!taxEnabled);
777:             recalcTotals();
778:         });
779: 
780:         $('#customerSelect').on('change', function () {
781:             var wholesale = isWholesaleCustomer();
