    if (!empty($filters['warehouse_id'])) {
        $sql .= ' AND o.warehouse_id = ?';
        $params[] = (int)$filters['warehouse_id'];
    }
    if (!empty($filters['status']) && in_array($filters['status'], ['pending', 'completed', 'cancelled'], true)) {
