const tab = await tools.browser.tabs.list();
const id = tab.tabs.find(t => t.url.includes('soundandvision'))?.id;
const data = await tools.browser.evaluate({
  tabID: id,
  script: `(() => {
    const clean = (s) => (s||'').replace(/\\s+/g,' ').trim();
    const qa = (s) => [...document.querySelectorAll(s)];
    const main = document.querySelector('.template-container') || document.body;
    const blocks = qa('.elementor-section, section, .elementor-widget-container').slice(0,80);
    const headings = qa('h1,h2,h3,h4').map(h => ({tag:h.tagName, text:clean(h.innerText).slice(0,90), cls:(h.className||'').toString().slice(0,40)}));
    const heroSlides = qa('[class*="slide"], .swiper-slide, .banner-slider').map(e => clean(e.innerText)).filter(t => t.length > 20).slice(0,8);
    const banners = qa('a[href*="product"], .banner, [class*="banner"]').map(e => clean(e.innerText)).filter(t => t.length > 5 && t.length < 220).slice(0,25);
    const footerText = clean((document.querySelector('footer')||{}).innerText).slice(0,1500);
    const topBar = clean((document.querySelector('.top-bar, [class*="topbar"], [class*="top-bar"]')||{}).innerText).slice(0,300);
    const services = qa('[class*="service"], [class*="feature"], [class*="trust"], [class*="benefit"]').map(e=>clean(e.innerText)).filter(t=>t.length>3&&t.length<120).slice(0,15);
    return {
      headings,
      heroSlides,
      banners,
      topBar,
      services,
      footerText,
      navText: clean((document.querySelector('.etheme-elementor-header-sticky')||{}).innerText).slice(0,500),
      productCardCount: qa('[class*="product"], li.product').length,
      categoryCards: qa('[class*="category"]').map(e=>clean(e.innerText)).filter(t=>t.length>4&&t.length<80).slice(0,20),
      bodyClasses: document.body.className,
    };
  })()`
});
return data;

