```css
.sf-header-inner { display:flex; flex-wrap:wrap; ... }
.sf-brand { order:1; flex:1 1 auto; max-width:none; }
.sf-actions { order:2; }
.sf-search-wrap { order:3; flex:1 0 100%; }
