/**
 * Opening sales balance per brand, keyed by the stored brand value.
 * Every configured brand is returned, with zero when no balance is saved.
 */
function brand_opening_balances($tenant_id = null) {
    global $current_user;
    $tenant_id = $tenant_id === null
        ? (int)($current_user->tenant_id ?? 0)
        : (int)$tenant_id;
    $out = [];
    foreach (product_brand_options() as $brand) {
        $out[$brand] = [
            'brand' => $brand,
            'opening_sales' => 0.0,
            'notes' => null,
            'updated_by' => null,
            'updated_at' => null,
        ];
    }
    if ($tenant_id <= 0) return $out;
    $rows = fetch_all(
        "SELECT brand, opening_sales, notes, updated_by, updated_at
           FROM brand_opening_balances
          WHERE tenant_id = ?
          ORDER BY brand",
        $tenant_id
    );
    foreach ($rows as $row) {
        $brand = trim((string)($row['brand'] ?? ''));
        if ($brand === '') continue;
        $out[$brand] = [
            'brand' => $brand,
            'opening_sales' => (float)($row['opening_sales'] ?? 0),
            'notes' => $row['notes'] ?? null,
            'updated_by' => $row['updated_by'] ?? null,
            'updated_at' => $row['updated_at'] ?? null,
        ];
    }
    return $out;
}

/** Total opening sales across all brands. */
function brand_opening_total($tenant_id = null) {
    $total = 0.0;
    foreach (brand_opening_balances($tenant_id) as $row) {
        $total += (float)($row['opening_sales'] ?? 0);
    }
    return $total;
}

/** Opening sales for one brand. */
function brand_opening_sales($brand, $tenant_id = null) {
    $balances = brand_opening_balances($tenant_id);
    return (float)($balances[(string)$brand]['opening_sales'] ?? 0);
}

