316: /**
317:  * Sales money that should be banked for one business date.
318:  * POS completed sales + invoice payments received, less accepted returns.
319:  */
320: function bank_sales_summary($tenant_id = null, $brand = '', $date = '') {
321:     global $current_user;
322:     $empty = [
323:         'date' => $date,
324:         'pos_sales' => 0.0,
325:         'invoice_payments' => 0.0,
326:         'returns' => 0.0,
327:         'gross' => 0.0,
328:         'net' => 0.0,
329:     ];
330:     if (!$current_user) return $empty;
331:     $tenant_id = $tenant_id === null ? (int)$current_user->tenant_id : (int)$tenant_id;
332:     $brand = capital_resolve_brand($brand);
333:     if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', (string)$date)) {
334:         $date = date('Y-m-d');
335:     }
336:     $empty['date'] = $date;
337: 
338:     // POS sales for the date.
339:     $params = [$tenant_id, $date];
340:     $wh = capital_shop_warehouse_condition('o.warehouse_id', $brand, $tenant_id, $params);
341:     $row = fetch_one(
342:         "SELECT COALESCE(SUM(o.total), 0) t FROM pos_orders o
343:           WHERE o.tenant_id = ? AND o.status = 'completed'
344:             AND DATE(o.order_date) = ?{$wh}",
345:         ...$params
346:     );
347:     $pos_sales = (float)($row['t'] ?? 0);
348: 
349:     // Invoice payments received on the date.
350:     $params = [$tenant_id, $date];
351:     $wh = capital_shop_warehouse_condition('i.warehouse_id', $brand, $tenant_id, $params);
352:     $row = fetch_one(
353:         "SELECT COALESCE(SUM(p.amount), 0) t
354:            FROM payments p
355:            JOIN invoices i ON i.invoice_id = p.invoice_id AND i.tenant_id = p.tenant_id
356:           WHERE p.tenant_id = ? AND DATE(p.payment_date) = ?{$wh}",
357:         ...$params
358:     );
359:     $invoice_payments = (float)($row['t'] ?? 0);
360: 
361:     // Accepted sales returns for the date.
362:     $params = [$tenant_id, $date];
363:     $return_sql = '';
364:     if ($brand !== '') {
365:         $params[] = $tenant_id;
366:         $params[] = $brand;
367:         $params[] = $tenant_id;
368:         $params[] = $brand;
369:         $return_sql = " AND (
370:             sr.shop_id IN (SELECT rs.shop_id FROM shops rs WHERE rs.tenant_id = ? AND rs.brand = ?)
371:             OR sr.warehouse_id IN (
372:                 SELECT rw.warehouse_id FROM warehouses rw
373:                   JOIN shops rs2 ON rs2.shop_id = rw.shop_id AND rs2.tenant_id = rw.tenant_id
374:                  WHERE rw.tenant_id = ? AND rs2.brand = ?
375:             )
376:         )";
377:     }
378:     $row = fetch_one(
379:         "SELECT COALESCE(SUM(sr.refund_amount), 0) t FROM sales_returns sr
380:           WHERE sr.tenant_id = ? AND sr.status = 'completed'
381:             AND DATE(sr.return_date) = ?{$return_sql}",
382:         ...$params
383:     );
384:     $returns = (float)($row['t'] ?? 0);
385: 
386:     $gross = $pos_sales + $invoice_payments;
387:     return [
388:         'date' => $date,
389:         'pos_sales' => $pos_sales,
390:         'invoice_payments' => $invoice_payments,
391:         'returns' => $returns,
392:         'gross' => $gross,
393:         'net' => max(0.0, $gross - $returns),
394:     ];
395: }
