422: /**
423:  * Bank account balances: capital in - capital out + sales banked.
424:  * Withdrawals are limited to the `available` figure of the selected bank.
425:  */
426: function bank_accounts_summary($tenant_id = null, $brand = '') {
427:     global $current_user;
428:     $empty = [
429:         'banks' => [],
430:         'capital_in' => 0.0,
431:         'capital_out' => 0.0,
432:         'sales_banked' => 0.0,
433:         'available' => 0.0,
434:     ];
435:     if (!$current_user) return $empty;
436:     $tenant_id = $tenant_id === null ? (int)$current_user->tenant_id : (int)$tenant_id;
437:     $brand = capital_resolve_brand($brand);
438:     $brand_sql = $brand !== '' ? ' AND brand = ?' : '';
439:     $params = $brand !== '' ? [$tenant_id, $brand] : [$tenant_id];
440: 
441:     $banks = [];
442:     if (capital_table_ready()) {
443:         $rows = fetch_all(
444:             "SELECT bank_name,
445:                     COALESCE(SUM(CASE WHEN movement_type = 'contribution' THEN amount ELSE 0 END), 0) capital_in,
446:                     COALESCE(SUM(CASE WHEN movement_type = 'withdrawal' THEN amount ELSE 0 END), 0) capital_out
447:                FROM capital_movements
448:               WHERE tenant_id = ?{$brand_sql}
449:               GROUP BY bank_name",
450:             ...$params
451:         );
452:         foreach ($rows as $row) {
453:             $key = strtolower(trim((string)$row['bank_name']));
454:             if ($key === '') continue;
455:             $banks[$key] = [
456:                 'bank_name' => (string)$row['bank_name'],
457:                 'capital_in' => (float)$row['capital_in'],
458:                 'capital_out' => (float)$row['capital_out'],
459:                 'sales_banked' => 0.0,
460:                 'available' => 0.0,
461:             ];
462:         }
463:     }
464: 
465:     if (db_table_exists('bank_sales_deposits')) {
466:         $rows = fetch_all(
467:             "SELECT bank_name, COALESCE(SUM(amount), 0) sales_banked
468:                FROM bank_sales_deposits
469:               WHERE tenant_id = ?{$brand_sql}
470:               GROUP BY bank_name",
471:             ...$params
472:         );
473:         foreach ($rows as $row) {
474:             $key = strtolower(trim((string)$row['bank_name']));
475:             if ($key === '') continue;
476:             if (!isset($banks[$key])) {
477:                 $banks[$key] = [
478:                     'bank_name' => (string)$row['bank_name'],
479:                     'capital_in' => 0.0,
480:                     'capital_out' => 0.0,
481:                     'sales_banked' => 0.0,
482:                     'available' => 0.0,
483:                 ];
484:             }
485:             $banks[$key]['sales_banked'] += (float)$row['sales_banked'];
486:         }
487:     }
488: 
489:     $total_in = 0.0;
490:     $total_out = 0.0;
491:     $total_sales = 0.0;
492:     $total_available = 0.0;
493:     foreach ($banks as &$bank) {
494:         $bank['available'] = $bank['capital_in'] - $bank['capital_out'] + $bank['sales_banked'];
495:         $total_in += $bank['capital_in'];
496:         $total_out += $bank['capital_out'];
497:         $total_sales += $bank['sales_banked'];
498:         $total_available += $bank['available'];
499:     }
500:     unset($bank);
501: 
502:     usort($banks, fn($a, $b) => strcasecmp($a['bank_name'], $b['bank_name']));
503: 
504:     return [
505:         'banks' => array_values($banks),
506:         'capital_in' => $total_in,
507:         'capital_out' => $total_out,
508:         'sales_banked' => $total_sales,
509:         'available' => $total_available,
510:     ];
511: }
