72:          JOIN invoices i ON i.invoice_id = sr.source_id AND i.tenant_id = sr.tenant_id
73:          WHERE sr.tenant_id = ? AND sr.source_type = 'invoice' AND sr.status = 'completed'"
74:             . $scope['sql'] . $returnDate['sql'],
75:         $tenantId, ...array_merge($scope['params'], $returnDate['params'])
76:     );
77: 
78:     $grossSales = (float)($gross['gross_sales'] ?? 0);
79:     $acceptedReturns = (float)($returns['accepted_returns'] ?? 0);
80:     return [
81:         'sale_count' => (int)($gross['sale_count'] ?? 0),
82:         'gross_sales' => $grossSales,
83:         'return_count' => (int)($returns['return_count'] ?? 0),
84:         'returned_qty' => (float)($returns['returned_qty'] ?? 0),
85:         'resale_qty' => (float)($returns['resale_qty'] ?? 0),
86:         'accepted_returns' => $acceptedReturns,
