126: function report_sales_channel_by_shop($channel, $from, $to) {
127:     $isPos = $channel === 'pos';
128:     if (!$isPos && $channel !== 'invoice') {
129:         throw new InvalidArgumentException('Unknown sales channel.');
130:     }
131: 
132:     $tenantId = report_tenant_id();
133:     $alias = $isPos ? 'o' : 'i';
134:     $table = $isPos ? 'pos_orders' : 'invoices';
135:     $sourceId = $isPos ? 'order_id' : 'invoice_id';
136:     $scope = report_sales_warehouse_condition($alias, 'warehouse_id');
137:     $saleDate = report_date_condition($alias . ($isPos ? '.order_date' : '.issue_date'), $from, $to);
138:     $statusJoin = $isPos ? '' : ' LEFT JOIN document_statuses ds ON ds.status_id = i.status_id AND ds.tenant_id = i.tenant_id';
139:     $eligible = $isPos ? "o.status = 'completed'" : report_invoice_eligibility_sql('i', 'ds');
140: 
141:     $grossRows = fetch_all(
142:         "SELECT $alias.warehouse_id, w.shop_id, s.name shop_name,
143:                 COUNT(*) sale_count, COALESCE(SUM($alias.total), 0) gross_sales
144:          FROM $table $alias
145:          $statusJoin
146:          LEFT JOIN warehouses w ON w.warehouse_id = $alias.warehouse_id AND w.tenant_id = $alias.tenant_id
147:          LEFT JOIN shops s ON s.shop_id = w.shop_id AND s.tenant_id = w.tenant_id
148:          WHERE $alias.tenant_id = ? AND $eligible" . $scope['sql'] . $saleDate['sql'] . "
149:          GROUP BY $alias.warehouse_id, w.shop_id, s.name",
150:         $tenantId, ...array_merge($scope['params'], $saleDate['params'])
151:     );
152: 
153:     $returnDate = report_date_condition('sr.return_date', $from, $to);
154:     $returnRows = fetch_all(
155:         "SELECT $alias.warehouse_id, w.shop_id, s.name shop_name,
156:                 COUNT(DISTINCT sr.return_id) return_count,
157:                 COALESCE(SUM(sri.quantity), 0) returned_qty,
158:                 COALESCE(SUM(sri.resale_quantity), 0) resale_qty,
159:                 COALESCE(SUM(sri.refund_amount), 0) accepted_returns
160:          FROM sales_returns sr
161:          JOIN sales_return_items sri ON sri.return_id = sr.return_id AND sri.tenant_id = sr.tenant_id
162:          JOIN $table $alias ON $alias.$sourceId = sr.source_id AND $alias.tenant_id = sr.tenant_id
163:          LEFT JOIN warehouses w ON w.warehouse_id = $alias.warehouse_id AND w.tenant_id = $alias.tenant_id
164:          LEFT JOIN shops s ON s.shop_id = w.shop_id AND s.tenant_id = w.tenant_id
165:          WHERE sr.tenant_id = ? AND sr.source_type = ? AND sr.status = 'completed'"
166:             . $scope['sql'] . $returnDate['sql'] . "
167:          GROUP BY $alias.warehouse_id, w.shop_id, s.name",
168:         $tenantId, $channel, ...array_merge($scope['params'], $returnDate['params'])
169:     );
170: 
171:     $rows = [];
172:     $init = function ($row) use ($isPos, &$rows) {
173:         $shopId = (int)($row['shop_id'] ?? 0);
174:         $key = $shopId > 0 ? 'shop:' . $shopId : 'unattributed';
175:         if (!isset($rows[$key])) {
176:             $rows[$key] = [
177:                 'shop_id' => $shopId > 0 ? $shopId : null,
178:                 'shop_name' => $shopId > 0 ? (string)$row['shop_name'] : 'Unattributed (historical)',
179:                 'pos_sale_count' => 0, 'pos_gross_sales' => 0.0, 'pos_accepted_returns' => 0.0,
180:                 'invoice_sale_count' => 0, 'invoice_gross_sales' => 0.0, 'invoice_accepted_returns' => 0.0,
181:                 'return_count' => 0, 'returned_qty' => 0.0, 'resale_qty' => 0.0,
182:             ];
183:         }
184:         return $key;
185:     };
186:     $prefix = $isPos ? 'pos' : 'invoice';
187:     foreach ($grossRows as $row) {
188:         $key = $init($row);
189:         $rows[$key][$prefix . '_sale_count'] += (int)$row['sale_count'];
190:         $rows[$key][$prefix . '_gross_sales'] += (float)$row['gross_sales'];
191:     }
192:     foreach ($returnRows as $row) {
193:         $key = $init($row);
194:         $rows[$key][$prefix . '_accepted_returns'] += (float)$row['accepted_returns'];
195:         $rows[$key]['return_count'] += (int)$row['return_count'];
196:         $rows[$key]['returned_qty'] += (float)$row['returned_qty'];
197:         $rows[$key]['resale_qty'] += (float)$row['resale_qty'];
198:     }
199:     return $rows;
200: }
