202: function report_sales_by_shop($from = '', $to = '') {
203:     $rows = report_sales_channel_by_shop('pos', $from, $to);
204:     foreach (report_sales_channel_by_shop('invoice', $from, $to) as $key => $invoiceRow) {
205:         if (!isset($rows[$key])) {
206:             $rows[$key] = $invoiceRow;
207:             continue;
208:         }
209:         $rows[$key]['invoice_sale_count'] += $invoiceRow['invoice_sale_count'];
210:         $rows[$key]['invoice_gross_sales'] += $invoiceRow['invoice_gross_sales'];
211:         $rows[$key]['invoice_accepted_returns'] += $invoiceRow['invoice_accepted_returns'];
212:         $rows[$key]['return_count'] += $invoiceRow['return_count'];
213:         $rows[$key]['returned_qty'] += $invoiceRow['returned_qty'];
214:         $rows[$key]['resale_qty'] += $invoiceRow['resale_qty'];
215:     }
216:     foreach ($rows as &$row) {
217:         $row['pos_net_sales'] = $row['pos_gross_sales'] - $row['pos_accepted_returns'];
218:         $row['invoice_net_sales'] = $row['invoice_gross_sales'] - $row['invoice_accepted_returns'];
219:         $row['net_sales'] = $row['pos_net_sales'] + $row['invoice_net_sales'];
220:         $row['sale_count'] = $row['pos_sale_count'] + $row['invoice_sale_count'];
221:     }
222:     unset($row);
223:     uasort($rows, fn($a, $b) => [($a['shop_id'] === null ? 1 : 0), $a['shop_name']] <=> [($b['shop_id'] === null ? 1 : 0), $b['shop_name']]);
224:     return array_values($rows);
225: }
