228: function report_sales_channel_by_product($channel, $from, $to) {
229:     $isPos = $channel === 'pos';
230:     if (!$isPos && $channel !== 'invoice') {
231:         throw new InvalidArgumentException('Unknown sales channel.');
232:     }
233: 
234:     $tenantId = report_tenant_id();
235:     $alias = $isPos ? 'o' : 'i';
236:     $itemAlias = $isPos ? 'oi' : 'ii';
237:     $table = $isPos ? 'pos_orders' : 'invoices';
238:     $itemTable = $isPos ? 'pos_order_items' : 'invoice_items';
239:     $sourceId = $isPos ? 'order_id' : 'invoice_id';
240:     $scope = report_sales_warehouse_condition($alias, 'warehouse_id');
241:     $saleDate = report_date_condition($alias . ($isPos ? '.order_date' : '.issue_date'), $from, $to);
242:     $statusJoin = $isPos ? '' : ' LEFT JOIN document_statuses ds ON ds.status_id = i.status_id AND ds.tenant_id = i.tenant_id';
243:     $eligible = $isPos ? "o.status = 'completed'" : report_invoice_eligibility_sql('i', 'ds');
244: 
245:     $grossRows = fetch_all(
246:         "SELECT COALESCE($itemAlias.product_id, 0) product_id,
247:                 COALESCE(p.name, $itemAlias.description, 'Unspecified product') product_name,
248:                 COALESCE(SUM($itemAlias.quantity), 0) sold_qty,
249:                 COALESCE(SUM($itemAlias.total), 0) gross_sales
250:          FROM $itemTable $itemAlias
251:          JOIN $table $alias ON $alias.$sourceId = $itemAlias.$sourceId AND $alias.tenant_id = ?
252:          $statusJoin
253:          LEFT JOIN products p ON p.product_id = $itemAlias.product_id AND p.tenant_id = $alias.tenant_id
254:          WHERE $alias.tenant_id = ? AND $eligible" . $scope['sql'] . $saleDate['sql'] . "
255:          GROUP BY COALESCE($itemAlias.product_id, 0), COALESCE(p.name, $itemAlias.description, 'Unspecified product')",
256:         $tenantId, $tenantId, ...array_merge($scope['params'], $saleDate['params'])
257:     );
258: 
259:     $returnDate = report_date_condition('sr.return_date', $from, $to);
260:     $returnRows = fetch_all(
261:         "SELECT COALESCE(sri.product_id, 0) product_id,
262:                 COALESCE(p.name, 'Unspecified product') product_name,
263:                 COALESCE(SUM(sri.quantity), 0) returned_qty,
264:                 COALESCE(SUM(sri.resale_quantity), 0) resale_qty,
265:                 COALESCE(SUM(sri.refund_amount), 0) accepted_returns
266:          FROM sales_returns sr
267:          JOIN sales_return_items sri ON sri.return_id = sr.return_id AND sri.tenant_id = sr.tenant_id
268:          JOIN $table $alias ON $alias.$sourceId = sr.source_id AND $alias.tenant_id = sr.tenant_id
269:          LEFT JOIN products p ON p.product_id = sri.product_id AND p.tenant_id = sr.tenant_id
270:          WHERE sr.tenant_id = ? AND sr.source_type = ? AND sr.status = 'completed'"
271:             . $scope['sql'] . $returnDate['sql'] . "
272:          GROUP BY COALESCE(sri.product_id, 0), COALESCE(p.name, 'Unspecified product')",
273:         $tenantId, $channel, ...array_merge($scope['params'], $returnDate['params'])
274:     );
275: 
276:     $rows = [];
277:     $init = function ($row) use (&$rows) {
278:         $productId = (int)$row['product_id'];
279:         $name = (string)$row['product_name'];
280:         $key = $productId > 0 ? 'product:' . $productId : 'description:' . $name;
281:         if (!isset($rows[$key])) {
282:             $rows[$key] = [
283:                 'product_id' => $productId > 0 ? $productId : null,
284:                 'product_name' => $name,
285:                 'pos_sold_qty' => 0.0, 'pos_gross_sales' => 0.0, 'pos_accepted_returns' => 0.0,
286:                 'invoice_sold_qty' => 0.0, 'invoice_gross_sales' => 0.0, 'invoice_accepted_returns' => 0.0,
287:                 'returned_qty' => 0.0, 'resale_qty' => 0.0,
288:             ];
289:         }
290:         return $key;
291:     };
292:     $prefix = $isPos ? 'pos' : 'invoice';
293:     foreach ($grossRows as $row) {
294:         $key = $init($row);
295:         $rows[$key][$prefix . '_sold_qty'] += (float)$row['sold_qty'];
296:         $rows[$key][$prefix . '_gross_sales'] += (float)$row['gross_sales'];
297:     }
298:     foreach ($returnRows as $row) {
299:         $key = $init($row);
300:         $rows[$key][$prefix . '_accepted_returns'] += (float)$row['accepted_returns'];
301:         $rows[$key]['returned_qty'] += (float)$row['returned_qty'];
302:         $rows[$key]['resale_qty'] += (float)$row['resale_qty'];
303:     }
304:     return $rows;
305: }
