307: function report_sales_by_product($from = '', $to = '') {
308:     $rows = report_sales_channel_by_product('pos', $from, $to);
309:     foreach (report_sales_channel_by_product('invoice', $from, $to) as $key => $invoiceRow) {
310:         if (!isset($rows[$key])) {
311:             $rows[$key] = $invoiceRow;
312:             continue;
313:         }
314:         $rows[$key]['invoice_sold_qty'] += $invoiceRow['invoice_sold_qty'];
315:         $rows[$key]['invoice_gross_sales'] += $invoiceRow['invoice_gross_sales'];
316:         $rows[$key]['invoice_accepted_returns'] += $invoiceRow['invoice_accepted_returns'];
317:         $rows[$key]['returned_qty'] += $invoiceRow['returned_qty'];
318:         $rows[$key]['resale_qty'] += $invoiceRow['resale_qty'];
319:     }
320:     foreach ($rows as &$row) {
321:         $row['sold_qty'] = $row['pos_sold_qty'] + $row['invoice_sold_qty'];
322:         $row['gross_sales'] = $row['pos_gross_sales'] + $row['invoice_gross_sales'];
323:         $row['accepted_returns'] = $row['pos_accepted_returns'] + $row['invoice_accepted_returns'];
324:         $row['net_qty'] = $row['sold_qty'] - $row['returned_qty'];
325:         $row['net_sales'] = $row['gross_sales'] - $row['accepted_returns'];
326:     }
327:     unset($row);
328:     uasort($rows, fn($a, $b) => $b['net_sales'] <=> $a['net_sales'] ?: strcmp($a['product_name'], $b['product_name']));
329:     return array_values($rows);
330: }
