333: /**
334:  * Sales grouped by product brand (GSP, TECHDOKTA, Unbranded).
335:  * POS and invoice line items are categorised by the product's brand.
336:  */
337: function report_sales_by_brand($from = '', $to = '') {
338:     $tenantId = report_tenant_id();
339:     $rows = [];
340: 
341:     $add = function ($key, array $values) use (&$rows) {
342:         $key = trim((string)$key);
343:         if ($key === '') $key = 'Unbranded';
344:         if (!isset($rows[$key])) {
345:             $rows[$key] = [
346:                 'brand_key' => $key,
347:                 'brand_label' => $key === 'Unbranded' ? 'Unbranded' : brand_label($key),
348:                 'sale_count' => 0,
349:                 'gross_sales' => 0.0,
350:                 'returned_qty' => 0.0,
351:                 'accepted_returns' => 0.0,
352:                 'opening_sales' => 0.0,
353:             ];
354:         }
355:         foreach ($values as $field => $value) {
356:             $rows[$key][$field] += $value;
357:         }
358:     };
359: 
360:     // POS gross by product brand.
361:     $posScope = report_sales_warehouse_condition('o', 'warehouse_id');
362:     $posDate = report_date_condition('o.order_date', $from, $to);
363:     $posGross = fetch_all(
364:         "SELECT COALESCE(NULLIF(TRIM(p.brand), ''), 'Unbranded') brand_key,
365:                 COUNT(DISTINCT o.order_id) sale_count,
366:                 COALESCE(SUM(oi.total), 0) gross_sales
367:            FROM pos_order_items oi
368:            JOIN pos_orders o ON o.order_id = oi.order_id AND o.tenant_id = ?
369:            LEFT JOIN products p ON p.product_id = oi.product_id AND p.tenant_id = o.tenant_id
370:           WHERE o.tenant_id = ? AND o.status = 'completed'" . $posScope['sql'] . $posDate['sql'] . "
371:           GROUP BY brand_key",
372:         $tenantId, $tenantId, ...array_merge($posScope['params'], $posDate['params'])
373:     );
374:     foreach ($posGross as $row) {
375:         $add($row['brand_key'], [
376:             'sale_count' => (int)$row['sale_count'],
377:             'gross_sales' => (float)$row['gross_sales'],
378:         ]);
379:     }
380: 
381:     // POS returns by product brand.
382:     $posReturnDate = report_date_condition('sr.return_date', $from, $to);
383:     $posReturns = fetch_all(
384:         "SELECT COALESCE(NULLIF(TRIM(p.brand), ''), 'Unbranded') brand_key,
385:                 COALESCE(SUM(sri.quantity), 0) returned_qty,
386:                 COALESCE(SUM(sri.refund_amount), 0) accepted_returns
387:            FROM sales_returns sr
388:            JOIN sales_return_items sri ON sri.return_id = sr.return_id AND sri.tenant_id = sr.tenant_id
389:            JOIN pos_orders o ON o.order_id = sr.source_id AND o.tenant_id = sr.tenant_id
390:            LEFT JOIN products p ON p.product_id = sri.product_id AND p.tenant_id = sr.tenant_id
391:           WHERE sr.tenant_id = ? AND sr.source_type = 'pos' AND sr.status = 'completed'"
392:             . $posScope['sql'] . $posReturnDate['sql'] . "
393:           GROUP BY brand_key",
394:         $tenantId, ...array_merge($posScope['params'], $posReturnDate['params'])
395:     );
396:     foreach ($posReturns as $row) {
397:         $add($row['brand_key'], [
398:             'returned_qty' => (float)$row['returned_qty'],
399:             'accepted_returns' => (float)$row['accepted_returns'],
400:         ]);
401:     }
402: 
403:     // Invoice gross by product brand.
404:     $invScope = report_sales_warehouse_condition('i', 'warehouse_id');
405:     $invDate = report_date_condition('i.issue_date', $from, $to);
406:     $eligible = report_invoice_eligibility_sql('i', 'ds');
407:     $invGross = fetch_all(
408:         "SELECT COALESCE(NULLIF(TRIM(p.brand), ''), 'Unbranded') brand_key,
409:                 COUNT(DISTINCT i.invoice_id) sale_count,
410:                 COALESCE(SUM(ii.total), 0) gross_sales
411:            FROM invoice_items ii
412:            JOIN invoices i ON i.invoice_id = ii.invoice_id AND i.tenant_id = ?
413:            LEFT JOIN document_statuses ds ON ds.status_id = i.status_id AND ds.tenant_id = i.tenant_id
414:            LEFT JOIN products p ON p.product_id = ii.product_id AND p.tenant_id = i.tenant_id
415:           WHERE i.tenant_id = ? AND $eligible" . $invScope['sql'] . $invDate['sql'] . "
416:           GROUP BY brand_key",
417:         $tenantId, $tenantId, ...array_merge($invScope['params'], $invDate['params'])
418:     );
419:     foreach ($invGross as $row) {
420:         $add($row['brand_key'], [
421:             'sale_count' => (int)$row['sale_count'],
422:             'gross_sales' => (float)$row['gross_sales'],
423:         ]);
424:     }
425: 
426:     // Invoice returns by product brand.
427:     $invReturnDate = report_date_condition('sr.return_date', $from, $to);
428:     $invReturns = fetch_all(
429:         "SELECT COALESCE(NULLIF(TRIM(p.brand), ''), 'Unbranded') brand_key,
430:                 COALESCE(SUM(sri.quantity), 0) returned_qty,
431:                 COALESCE(SUM(sri.refund_amount), 0) accepted_returns
432:            FROM sales_returns sr
433:            JOIN sales_return_items sri ON sri.return_id = sr.return_id AND sri.tenant_id = sr.tenant_id
434:            JOIN invoices i ON i.invoice_id = sr.source_id AND i.tenant_id = sr.tenant_id
435:            LEFT JOIN products p ON p.product_id = sri.product_id AND p.tenant_id = sr.tenant_id
436:           WHERE sr.tenant_id = ? AND sr.source_type = 'invoice' AND sr.status = 'completed'"
437:             . $invScope['sql'] . $invReturnDate['sql'] . "
438:           GROUP BY brand_key",
439:         $tenantId, ...array_merge($invScope['params'], $invReturnDate['params'])
440:     );
441:     foreach ($invReturns as $row) {
442:         $add($row['brand_key'], [
443:             'returned_qty' => (float)$row['returned_qty'],
444:             'accepted_returns' => (float)$row['accepted_returns'],
445:         ]);
446:     }
447: 
448:     // All-time opening balance for each brand.
449:     $openingBalances = brand_opening_balances($tenantId);
450:     foreach ($openingBalances as $brandKey => $openingRow) {
451:         $openingAmount = (float)($openingRow['opening_sales'] ?? 0);
452:         if (!isset($rows[$brandKey])) {
453:             if ($openingAmount <= 0) {
454:                 continue;
455:             }
456:             $rows[$brandKey] = [
457:                 'brand_key' => $brandKey,
458:                 'brand_label' => brand_label($brandKey),
459:                 'sale_count' => 0,
460:                 'gross_sales' => 0.0,
461:                 'returned_qty' => 0.0,
462:                 'accepted_returns' => 0.0,
463:                 'opening_sales' => 0.0,
464:             ];
465:         }
466:         $rows[$brandKey]['opening_sales'] = $openingAmount;
467:     }
468: 
469:     // Shop-specific opening balances are grouped under the shop's brand.
470:     foreach (shop_opening_balances($tenantId) as $shopOpeningRow) {
471:         $shopOpeningAmount = (float)($shopOpeningRow['opening_sales'] ?? 0);
472:         if ($shopOpeningAmount <= 0) {
473:             continue;
474:         }
475:         $shopOpeningBrand = trim((string)($shopOpeningRow['shop_brand'] ?? ''));
476:         $shopOpeningKey = $shopOpeningBrand !== '' ? $shopOpeningBrand : 'Unbranded';
477:         if (!isset($rows[$shopOpeningKey])) {
478:             $rows[$shopOpeningKey] = [
479:                 'brand_key' => $shopOpeningKey,
