15: /**
16:  * Capital contributions, withdrawals and bank breakdown for a tenant.
17:  * A Mini Admin is always limited to their own brand.
18:  */
19: function capital_summary($tenant_id = null, $brand = '') {
20:     global $current_user;
21:     $empty = [
22:         'contributions' => 0.0,
23:         'withdrawals'   => 0.0,
