26:         'movements'     => 0,
27:         'banks'         => [],
28:     ];
29:     if (!$current_user) return $empty;
30:     $tenant_id = $tenant_id === null ? (int)$current_user->tenant_id : (int)$tenant_id;
31:     $brand = capital_resolve_brand($brand);
32:     if (!capital_table_ready()) return $empty;
33: 
34:     $brand_sql = $brand !== '' ? ' AND brand = ?' : '';
35:     $params = $brand !== '' ? [$tenant_id, $brand] : [$tenant_id];
36: 
37:     $row = fetch_one(
38:         "SELECT COALESCE(SUM(CASE WHEN movement_type = 'contribution' THEN amount ELSE 0 END), 0) contributions,
39:                 COALESCE(SUM(CASE WHEN movement_type = 'withdrawal' THEN amount ELSE 0 END), 0) withdrawals,
40:                 COUNT(*) movements
41:            FROM capital_movements
42:           WHERE tenant_id = ?{$brand_sql}",
43:         ...$params
44:     ) ?: [];
45: 
46:     $bank_rows = fetch_all(
47:         "SELECT bank_name,
48:                 COALESCE(SUM(CASE WHEN movement_type = 'contribution' THEN amount ELSE 0 END), 0) contributions,
49:                 COALESCE(SUM(CASE WHEN movement_type = 'withdrawal' THEN amount ELSE 0 END), 0) withdrawals
50:            FROM capital_movements
51:           WHERE tenant_id = ?{$brand_sql}
52:           GROUP BY bank_name
53:           ORDER BY bank_name",
54:         ...$params
55:     );
56: 
57:     $banks = [];
58:     $bank_net = 0.0;
59:     foreach ($bank_rows as $bank_row) {
60:         $net = (float)$bank_row['contributions'] - (float)$bank_row['withdrawals'];
61:         $bank_net += $net;
62:         $banks[] = [
63:             'bank_name'     => (string)$bank_row['bank_name'],
64:             'contributions' => (float)$bank_row['contributions'],
65:             'withdrawals'   => (float)$bank_row['withdrawals'],
66:             'net'           => $net,
67:         ];
68:     }
69: 
70:     return [
71:         'contributions' => (float)($row['contributions'] ?? 0),
72:         'withdrawals'   => (float)($row['withdrawals'] ?? 0),
73:         'net'           => (float)($row['contributions'] ?? 0) - (float)($row['withdrawals'] ?? 0),
74:         'bank_net'      => $bank_net,
75:         'movements'     => (int)($row['movements'] ?? 0),
76:         'banks'         => $banks,
77:     ];
