299:     $brand = capital_resolve_brand($brand);
300:     $bank_name = trim((string)$bank_name);
301:     if ($tenant_id <= 0 || $brand === '' || $bank_name === '') return '';
302: 
303:     $sql = "SELECT bank_name FROM capital_movements
304:              WHERE tenant_id = ? AND brand = ? AND LOWER(TRIM(bank_name)) = LOWER(TRIM(?))";
305:     $params = [$tenant_id, $brand, $bank_name];
306:     if (db_table_exists('bank_sales_deposits')) {
307:         $sql .= " UNION SELECT bank_name FROM bank_sales_deposits
308:                    WHERE tenant_id = ? AND brand = ? AND LOWER(TRIM(bank_name)) = LOWER(TRIM(?))";
