321:     global $current_user;
322:     $empty = [
323:         'date' => $date,
324:         'pos_sales' => 0.0,
325:         'invoice_payments' => 0.0,
326:         'returns' => 0.0,
327:         'gross' => 0.0,
328:         'net' => 0.0,
