/** Find an existing bank account name for a brand (case-insensitive). */
function bank_canonical_name($tenant_id, $brand, $bank_name) {
    $tenant_id = (int)$tenant_id;
    $brand = capital_resolve_brand($brand);
    $bank_name = trim((string)$bank_name);
    if ($tenant_id <= 0 || $brand === '' || $bank_name === '') return '';

    $sql = "SELECT bank_name FROM capital_movements
             WHERE tenant_id = ? AND brand = ? AND LOWER(TRIM(bank_name)) = LOWER(TRIM(?))";
    $params = [$tenant_id, $brand, $bank_name];
    if (db_table_exists('bank_sales_deposits')) {
        $sql .= " UNION SELECT bank_name FROM bank_sales_deposits
                   WHERE tenant_id = ? AND brand = ? AND LOWER(TRIM(bank_name)) = LOWER(TRIM(?))";
        array_push($params, $tenant_id, $brand, $bank_name);
    }
    $sql .= " LIMIT 1";
    $row = fetch_one($sql, ...$params);
    return $row ? (string)$row['bank_name'] : '';
}

