/**
 * Bank account balances: capital in - capital out + sales banked.
 * Withdrawals are limited to the `available` figure of the selected bank.
 */
function bank_accounts_summary($tenant_id = null, $brand = '') {
    global $current_user;
    $empty = [
        'banks' => [],
        'capital_in' => 0.0,
        'capital_out' => 0.0,
        'sales_banked' => 0.0,
        'available' => 0.0,
    ];
    if (!$current_user) return $empty;
    $tenant_id = $tenant_id === null ? (int)$current_user->tenant_id : (int)$tenant_id;
    $brand = capital_resolve_brand($brand);
    $brand_sql = $brand !== '' ? ' AND brand = ?' : '';
    $params = $brand !== '' ? [$tenant_id, $brand] : [$tenant_id];

    $banks = [];
    if (capital_table_ready()) {
        $rows = fetch_all(
            "SELECT bank_name,
                    COALESCE(SUM(CASE WHEN movement_type = 'contribution' THEN amount ELSE 0 END), 0) capital_in,
                    COALESCE(SUM(CASE WHEN movement_type = 'withdrawal' THEN amount ELSE 0 END), 0) capital_out
               FROM capital_movements
              WHERE tenant_id = ?{$brand_sql}
              GROUP BY bank_name",
            ...$params
        );
        foreach ($rows as $row) {
            $key = strtolower(trim((string)$row['bank_name']));
            if ($key === '') continue;
            $banks[$key] = [
                'bank_name' => (string)$row['bank_name'],
                'capital_in' => (float)$row['capital_in'],
                'capital_out' => (float)$row['capital_out'],
                'sales_banked' => 0.0,
                'available' => 0.0,
            ];
        }
    }

    if (db_table_exists('bank_sales_deposits')) {
        $rows = fetch_all(
            "SELECT bank_name, COALESCE(SUM(amount), 0) sales_banked
               FROM bank_sales_deposits
              WHERE tenant_id = ?{$brand_sql}
              GROUP BY bank_name",
            ...$params
        );
        foreach ($rows as $row) {
            $key = strtolower(trim((string)$row['bank_name']));
            if ($key === '') continue;
            if (!isset($banks[$key])) {
                $banks[$key] = [
                    'bank_name' => (string)$row['bank_name'],
                    'capital_in' => 0.0,
                    'capital_out' => 0.0,
                    'sales_banked' => 0.0,
                    'available' => 0.0,
                ];
            }
            $banks[$key]['sales_banked'] += (float)$row['sales_banked'];
        }
    }

    $total_in = 0.0;
    $total_out = 0.0;
    $total_sales = 0.0;
    $total_available = 0.0;
    foreach ($banks as &$bank) {
        $bank['available'] = $bank['capital_in'] - $bank['capital_out'] + $bank['sales_banked'];
        $total_in += $bank['capital_in'];
        $total_out += $bank['capital_out'];
        $total_sales += $bank['sales_banked'];
        $total_available += $bank['available'];
    }
    unset($bank);

    usort($banks, fn($a, $b) => strcasecmp($a['bank_name'], $b['bank_name']));

    return [
        'banks' => array_values($banks),
        'capital_in' => $total_in,
        'capital_out' => $total_out,
        'sales_banked' => $total_sales,
        'available' => $total_available,
    ];
}

