/* -------------------------------------------------------------------------
 * Per-shop cash
 *
 * Cash in hand belongs to the brand as a whole. The system administrator can
 * give part of it to a shop; shop cash sales, refunds, expenses and purchases
 * then move that shop's balance. Closing business sweeps the shop balance back
 * into the brand's unallocated cash. Bank, card and mobile-money receipts go
 * straight to the brand bank and never touch a shop balance.
 * ---------------------------------------------------------------------- */

/** True when the shop cash transfer table exists (migration 042). */
function shop_cash_transfers_table_ready() {
    return db_table_exists('shop_cash_transfers');
}

/** Shops belonging to a brand ('' returns every shop). */
function shop_cash_shop_rows($tenant_id, $brand = '') {
    $tenant_id = (int)$tenant_id;
    $brand = capital_resolve_brand($brand);
    if ($tenant_id <= 0) return [];
    $brand_sql = $brand !== '' ? ' AND s.brand = ?' : '';
    $params = $brand !== '' ? [$tenant_id, $brand] : [$tenant_id];
    return fetch_all(
        "SELECT s.shop_id, s.name, s.code, s.brand, s.is_active
           FROM shops s
          WHERE s.tenant_id = ?{$brand_sql}
          ORDER BY s.name",
        ...$params
    );
}

/**
 * Cash balance for every shop of a brand ('' = every shop).
 *
 * balance = money given by the brand
 *         - money handed back to the brand
 *         + cash POS and invoice receipts
 *         - cash refunds, expenses and supplier payments
 */
function shop_cash_balances($tenant_id = null, $brand = '') {
    global $current_user;
    if (!$current_user) return [];
    $tenant_id = $tenant_id === null ? (int)$current_user->tenant_id : (int)$tenant_id;
    $brand = capital_resolve_brand($brand);

    $shops = shop_cash_shop_rows($tenant_id, $brand);
    if (!$shops) return [];

    $rows = [];
    foreach ($shops as $shop) {
        $sid = (int)$shop['shop_id'];
        $rows[$sid] = [
            'shop_id'         => $sid,
            'name'            => (string)$shop['name'],
            'code'            => (string)$shop['code'],
            'brand'           => (string)($shop['brand'] ?? ''),
            'is_active'       => (int)$shop['is_active'],
            'distributed_in'  => 0.0,
            'collected_out'   => 0.0,
            'pos_cash'        => 0.0,
            'invoice_cash'    => 0.0,
            'cash_refunds'    => 0.0,
            'cash_expenses'   => 0.0,
            'cash_purchases'  => 0.0,
            'balance'         => 0.0,
        ];
    }

    // Brand-to-shop and shop-to-brand cash transfers.
    if (shop_cash_transfers_table_ready()) {
        $brand_sql = $brand !== '' ? ' AND t.brand = ?' : '';
        $params = $brand !== '' ? [$tenant_id, $brand] : [$tenant_id];
        foreach (fetch_all(
            "SELECT t.shop_id,
                    SUM(CASE WHEN t.direction = 'brand_to_shop' THEN t.amount ELSE 0 END) distributed_in,
                    SUM(CASE WHEN t.direction = 'shop_to_brand' THEN t.amount ELSE 0 END) collected_out
               FROM shop_cash_transfers t
              WHERE t.tenant_id = ?{$brand_sql}
              GROUP BY t.shop_id",
            ...$params
        ) as $r) {
            $sid = (int)$r['shop_id'];
            if (!isset($rows[$sid])) continue;
            $rows[$sid]['distributed_in'] = (float)$r['distributed_in'];
            $rows[$sid]['collected_out'] = (float)$r['collected_out'];
        }
    }

    $shop_sql = $brand !== '' ? ' AND s.brand = ?' : '';
    $cash_receipt = capital_payment_account_expr('pm', 'bank');
    $cash_outflow = capital_payment_account_expr('pm', 'cash');

    // POS cash payments, attributed through the order's warehouse shop.
    $params = $brand !== '' ? [$tenant_id, $brand] : [$tenant_id];
    foreach (fetch_all(
        "SELECT w.shop_id, COALESCE(SUM(pp.amount), 0) t
           FROM pos_payments pp
           JOIN pos_orders o ON o.order_id = pp.order_id AND o.tenant_id = ?
           JOIN warehouses w ON w.warehouse_id = o.warehouse_id AND w.tenant_id = o.tenant_id
           JOIN shops s ON s.shop_id = w.shop_id AND s.tenant_id = w.tenant_id
           LEFT JOIN payment_methods pm ON pm.payment_method_id = pp.payment_method_id AND pm.tenant_id = o.tenant_id
          WHERE o.status = 'completed' AND {$cash_receipt} = 'cash'{$shop_sql}
          GROUP BY w.shop_id",
        ...$params
    ) as $r) {
        $sid = (int)$r['shop_id'];
        if (isset($rows[$sid])) $rows[$sid]['pos_cash'] = (float)$r['t'];
    }

    // Invoice cash payments, attributed through the invoice warehouse shop.
    $params = $brand !== '' ? [$tenant_id, $brand] : [$tenant_id];
    foreach (fetch_all(
        "SELECT w.shop_id, COALESCE(SUM(p.amount), 0) t
           FROM payments p
           JOIN invoices i ON i.invoice_id = p.invoice_id AND i.tenant_id = p.tenant_id
           JOIN warehouses w ON w.warehouse_id = i.warehouse_id AND w.tenant_id = i.tenant_id
           JOIN shops s ON s.shop_id = w.shop_id AND s.tenant_id = w.tenant_id
           LEFT JOIN payment_methods pm ON pm.payment_method_id = p.payment_method_id AND pm.tenant_id = p.tenant_id
          WHERE p.tenant_id = ? AND {$cash_receipt} = 'cash'{$shop_sql}
          GROUP BY w.shop_id",
        ...$params
    ) as $r) {
        $sid = (int)$r['shop_id'];
        if (isset($rows[$sid])) $rows[$sid]['invoice_cash'] = (float)$r['t'];
    }

    // Cash refunds. sales_returns.shop_id is authoritative; older rows fall
    // back to the return warehouse's shop.
    $params = $brand !== '' ? [$tenant_id, $brand] : [$tenant_id];
    foreach (fetch_all(
        "SELECT COALESCE(sr.shop_id, w.shop_id) shop_id, COALESCE(SUM(sr.refund_amount), 0) t
           FROM sales_returns sr
           LEFT JOIN warehouses w ON w.warehouse_id = sr.warehouse_id AND w.tenant_id = sr.tenant_id
           LEFT JOIN payment_methods pm ON pm.payment_method_id = sr.refund_method_id AND pm.tenant_id = sr.tenant_id
           JOIN shops s ON s.shop_id = COALESCE(sr.shop_id, w.shop_id) AND s.tenant_id = sr.tenant_id
          WHERE sr.tenant_id = ? AND sr.status = 'completed'
            AND sr.source_type IN ('pos', 'invoice') AND {$cash_outflow} = 'cash'{$shop_sql}
          GROUP BY COALESCE(sr.shop_id, w.shop_id)",
        ...$params
    ) as $r) {
        $sid = (int)$r['shop_id'];
        if (isset($rows[$sid])) $rows[$sid]['cash_refunds'] = (float)$r['t'];
    }

    // Cash expenses assigned to a shop.
    if (capital_column_exists('expenses', 'shop_id')) {
        $params = $brand !== '' ? [$tenant_id, $brand] : [$tenant_id];
        foreach (fetch_all(
            "SELECT e.shop_id, COALESCE(SUM(e.amount), 0) t
               FROM expenses e
               JOIN shops s ON s.shop_id = e.shop_id AND s.tenant_id = e.tenant_id
               LEFT JOIN payment_methods pm ON pm.payment_method_id = e.payment_method_id AND pm.tenant_id = e.tenant_id
              WHERE e.tenant_id = ? AND e.shop_id IS NOT NULL AND {$cash_outflow} = 'cash'{$shop_sql}
              GROUP BY e.shop_id",
            ...$params
        ) as $r) {
            $sid = (int)$r['shop_id'];
            if (isset($rows[$sid])) $rows[$sid]['cash_expenses'] = (float)$r['t'];
        }
    }

    // Cash supplier payments assigned to a shop.
    if (capital_column_exists('purchases', 'shop_id')) {
        $params = $brand !== '' ? [$tenant_id, $brand] : [$tenant_id];
        foreach (fetch_all(
            "SELECT pu.shop_id, COALESCE(SUM(pu.amount_paid), 0) t
               FROM purchases pu
               JOIN shops s ON s.shop_id = pu.shop_id AND s.tenant_id = pu.tenant_id
               LEFT JOIN payment_methods pm ON pm.payment_method_id = pu.payment_method_id AND pm.tenant_id = pu.tenant_id
              WHERE pu.tenant_id = ? AND pu.shop_id IS NOT NULL AND {$cash_outflow} = 'cash'{$shop_sql}
              GROUP BY pu.shop_id",
            ...$params
        ) as $r) {
            $sid = (int)$r['shop_id'];
            if (isset($rows[$sid])) $rows[$sid]['cash_purchases'] = (float)$r['t'];
        }
    }

    foreach ($rows as &$row) {
        $row['balance'] = $row['distributed_in']
            - $row['collected_out']
            + $row['pos_cash']
            + $row['invoice_cash']
            - $row['cash_refunds']
            - $row['cash_expenses']
            - $row['cash_purchases'];
    }
    unset($row);

    return array_values($rows);
}

/** Cash balance for one shop, or 0.0 when it is not visible. */
function shop_cash_balance($tenant_id, $brand, $shop_id) {
    $shop_id = (int)$shop_id;
    if ($shop_id <= 0) return 0.0;
    foreach (shop_cash_balances($tenant_id, $brand) as $row) {
        if ((int)$row['shop_id'] === $shop_id) return (float)$row['balance'];
    }
    return 0.0;
}

/**
 * Brand cash that has not been assigned to a shop.
 * Brand cash in hand is the total; shop balances are a partition of it.
 */
function brand_unallocated_cash($tenant_id = null, $brand = '') {
    global $current_user;
    if (!$current_user) return 0.0;
    $tenant_id = $tenant_id === null ? (int)$current_user->tenant_id : (int)$tenant_id;
    $brand = capital_resolve_brand($brand);
    $breakdown = brand_capital_breakdown($tenant_id, $brand);
    $allocated = 0.0;
    foreach (shop_cash_balances($tenant_id, $brand) as $row) {
        $allocated += (float)$row['balance'];
    }
    return (float)$breakdown['cash'] - $allocated;
}

/** Brand cash split into total, shop-allocated and unallocated amounts. */
function brand_shop_cash_summary($tenant_id = null, $brand = '') {
    global $current_user;
    if (!$current_user) {
        return ['brand' => '', 'cash' => 0.0, 'allocated' => 0.0, 'unallocated' => 0.0, 'shops' => []];
    }
    $tenant_id = $tenant_id === null ? (int)$current_user->tenant_id : (int)$tenant_id;
    $brand = capital_resolve_brand($brand);
    $breakdown = brand_capital_breakdown($tenant_id, $brand);
    $shops = shop_cash_balances($tenant_id, $brand);
    $allocated = 0.0;
    foreach ($shops as $row) $allocated += (float)$row['balance'];
    return [
        'brand'       => $brand,
        'cash'        => (float)$breakdown['cash'],
        'allocated'   => $allocated,
        'unallocated' => (float)$breakdown['cash'] - $allocated,
        'shops'       => $shops,
    ];
}

/** Shop cash transfer history for a brand (optionally one shop). */
function shop_cash_transfer_history($tenant_id = null, $brand = '', $shop_id = 0, $limit = 200) {
    global $current_user;
    if (!$current_user || !shop_cash_transfers_table_ready()) return [];
    $tenant_id = $tenant_id === null ? (int)$current_user->tenant_id : (int)$tenant_id;
    $brand = capital_resolve_brand($brand);
    $shop_id = (int)$shop_id;
    $limit = max(1, min(1000, (int)$limit));
    $sql = "SELECT t.*, s.name shop_name, s.code shop_code,
                   TRIM(CONCAT(COALESCE(u.first_name, ''), ' ', COALESCE(u.last_name, ''))) entered_by_name,
                   u.username entered_by_username
              FROM shop_cash_transfers t
              JOIN shops s ON s.shop_id = t.shop_id AND s.tenant_id = t.tenant_id
              LEFT JOIN users u ON u.user_id = t.created_by
             WHERE t.tenant_id = ?";
    $params = [$tenant_id];
    if ($brand !== '') {
        $sql .= " AND t.brand = ?";
        $params[] = $brand;
    }
    if ($shop_id > 0) {
        $sql .= " AND t.shop_id = ?";
        $params[] = $shop_id;
    }
    $sql .= " ORDER BY t.entry_date DESC, t.transfer_id DESC LIMIT {$limit}";
    return fetch_all($sql, ...$params);
}

/**
 * Record a cash transfer between a brand and one of its shops.
 * Throws a RuntimeException when the shop, brand or available cash is invalid.
 */
function record_shop_cash_transfer($tenant_id, $brand, $shop_id, $direction, $amount, $entry_date, $reference, $notes, $user_id) {
    global $conn, $current_user;
    $tenant_id = (int)$tenant_id;
    $brand = capital_resolve_brand($brand);
    $shop_id = (int)$shop_id;
    $amount = round((float)$amount, 2);
    $direction = in_array($direction, ['brand_to_shop', 'shop_to_brand'], true) ? $direction : '';

    if ($tenant_id <= 0 || $brand === '' || $shop_id <= 0) {
        throw new RuntimeException('Select a brand and one of its shops.');
    }
    if ($direction === '') {
        throw new RuntimeException('Select whether cash is going to the shop or back to the brand.');
    }
    if ($amount <= 0) {
        throw new RuntimeException('Enter a cash amount greater than zero.');
    }
    if (!preg_match('/^\d{4}-\d{2}-\d{2}$/', (string)$entry_date) || !strtotime((string)$entry_date)) {
        $entry_date = date('Y-m-d');
    }
    if (mb_strlen((string)$reference) > 100) {
        throw new RuntimeException('The reference must be 100 characters or fewer.');
    }
    if (!shop_cash_transfers_table_ready()) {
        throw new RuntimeException('Shop cash is not available yet. Run migration 042 first.');
    }

    $shop = fetch_one(
        "SELECT shop_id, name, brand FROM shops WHERE shop_id = ? AND tenant_id = ?",
        $shop_id,
        $tenant_id
    );
    if (!$shop) {
        throw new RuntimeException('Shop not found.');
    }
    if (trim((string)($shop['brand'] ?? '')) !== $brand) {
        throw new RuntimeException('The selected shop does not belong to this brand.');
    }

    $conn->begin_transaction();
    try {
        // Serialise transfers for this shop so two requests cannot spend the
        // same cash twice.
        fetch_all(
            "SELECT transfer_id FROM shop_cash_transfers
              WHERE tenant_id = ? AND shop_id = ? FOR UPDATE",
            $tenant_id,
            $shop_id
        );

        if ($direction === 'brand_to_shop') {
            $available = brand_unallocated_cash($tenant_id, $brand);
            if ($amount > $available + 0.005) {
                throw new RuntimeException(
                    'The amount exceeds the unallocated brand cash. Available: '
                    . money($available, tenant_currency())
                );
            }
        } else {
            $available = shop_cash_balance($tenant_id, $brand, $shop_id);
            if ($amount > $available + 0.005) {
                throw new RuntimeException(
                    'The amount exceeds this shop\'s cash balance. Available: '
                    . money($available, tenant_currency())
                );
            }
        }

        $transfer_id = db_insert('shop_cash_transfers', [
            'tenant_id'  => $tenant_id,
            'brand'      => $brand,
            'shop_id'    => $shop_id,
            'direction'  => $direction,
            'amount'     => $amount,
            'entry_date' => $entry_date,
            'reference'  => $reference !== '' ? $reference : null,
            'notes'      => $notes !== '' ? $notes : null,
            'created_by' => (int)$user_id,
        ]);
        if (!$transfer_id) {
            throw new RuntimeException('Could not save the shop cash transfer.');
        }
        $conn->commit();
    } catch (Throwable $ex) {
        $conn->rollback();
        throw $ex;
    }

    return [
        'transfer_id' => (int)$transfer_id,
        'shop_id'     => $shop_id,
        'shop_name'   => (string)$shop['name'],
        'amount'      => $amount,
        'direction'   => $direction,
        'entry_date'  => $entry_date,
    ];
}

/**
 * Close a shop: sweep its whole cash balance into the brand's cash in hand.
 * Returns the recorded transfer details.
 */
function close_shop_cash($tenant_id, $brand, $shop_id, $user_id, $entry_date = '', $reference = '', $notes = '') {
    $balance = shop_cash_balance($tenant_id, $brand, $shop_id);
    if ($balance <= 0.005) {
        throw new RuntimeException('This shop has no cash balance to close.');
    }
    return record_shop_cash_transfer(
        $tenant_id,
        $brand,
        $shop_id,
        'shop_to_brand',
        $balance,
        $entry_date,
        $reference,
        $notes,
        $user_id
    );
}
