/** Total opening sales across all shops. */
function shop_opening_total($tenant_id = null) {
    $total = 0.0;
    foreach (shop_opening_balances($tenant_id) as $row) {
        $total += (float)($row['opening_sales'] ?? 0);
    }
    return $total;
}

