946:     // Invoice payments received on the date.
947:     $params = [$tenant_id, $date];
948:     $wh = capital_shop_warehouse_condition('i.warehouse_id', $brand, $tenant_id, $params);
949:     $row = fetch_one(
950:         "SELECT COALESCE(SUM(CASE WHEN {$acct} = 'cash' THEN p.amount ELSE 0 END), 0) cash_amount,
951:                 COALESCE(SUM(CASE WHEN {$acct} = 'bank' THEN p.amount ELSE 0 END), 0) bank_amount
952:            FROM payments p
953:            JOIN invoices i ON i.invoice_id = p.invoice_id AND i.tenant_id = p.tenant_id
954:            LEFT JOIN payment_methods pm ON pm.payment_method_id = p.payment_method_id AND pm.tenant_id = p.tenant_id
955:           WHERE p.tenant_id = ? AND DATE(p.payment_date) = ?{$wh}",
956:         ...$params
957:     ) ?: [];
958:     $invoice_cash = (float)($row['cash_amount'] ?? 0);
959:     $invoice_bank = (float)($row['bank_amount'] ?? 0);
960: 
961:     // POS/invoice refunds paid on the date.
