993:         'cash_receipts' => $cash_receipts,
994:         'bank_receipts' => $bank_receipts,
995:         'cash_net' => $cash_net,
996:         'bank_net' => $bank_net,
997:         'gross' => $cash_receipts,
998:         'net' => $cash_net,
999:     ];
