15: /** True when a column exists. Cached because capital screens query it often. */
16: function capital_column_exists($table, $column) {
17:     static $cache = [];
18:     $table = preg_replace('/[^a-zA-Z0-9_]/', '', (string)$table);
19:     $column = preg_replace('/[^a-zA-Z0-9_]/', '', (string)$column);
20:     if ($table === '' || $column === '') return false;
21:     $key = $table . '.' . $column;
22:     if (array_key_exists($key, $cache)) return $cache[$key];
23:     $found = false;
24:     if (db_table_exists($table)) {
25:         foreach (fetch_all("SHOW COLUMNS FROM `{$table}`") as $row) {
26:             if (strcasecmp((string)($row['Field'] ?? ''), $column) === 0) {
27:                 $found = true;
28:                 break;
29:             }
30:         }
31:     }
32:     $cache[$key] = $found;
33:     return $found;
34: }
